
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = v => String(v == null ? '' : v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list = value => Array.isArray(value) ? value : (value && value.items) || [];
const types = {farm:'农场',channel:'沟渠',field:'田块',pond:'池塘',facility:'设施',production_system:'生产系统',production_batch:'生产批次',lot:'物料批次',material_lot:'物料批次',package:'包装',logistic_unit:'物流单元',device:'设备',measurement_point:'测点',sample:'样本',organization:'组织'};
const labels = {device:'设备与采集',device_record:'设备记录',capture_policy:'采集计划',inspection:'现场巡检',irrigation:'灌排作业',maintenance:'设备维护',incident:'异常情况',camera_snapshot:'摄像头快照',camera_video:'摄像头录像',gate_status:'闸门状态',manual_note:'设备说明',disabled:'已停用',identity:'对象身份',space:'空间关系',event:'事件参与',assertion:'断言',harvest:'采收',split:'拆批',merge:'并批',transform:'加工',package:'包装',ship:'发货',receive:'签收',candidate:'待审核',accepted:'已采用',active:'有效',withdrawn:'已撤回',published:'已发布',recalled:'召回中',rejected:'未采用',reported:'已报告',measured:'实测',estimated:'估算',model:'模型候选',forecast:'预报',document:'文档',image:'图像',video:'视频',sensor:'传感器',weather:'天气',remote_sensing:'遥感',manual:'手工记录',official_api:'官方接口',dynamic:'动态集合',snapshot:'固定快照',quality:'质量',production:'生产',spatial:'空间',material:'物料',observation:'观测',evidence:'证据',classification:'分类'};
const state = {view:'overview',actor:null,token:'',data:{},graph:null,graphKey:'',dimension:'',search:'',busy:false,refreshErrors:[],refreshEpoch:0};
const navs = [['overview','◈','数据库总览'],['domains','◇','本体管理'],['intake','⌁','数据接入'],['objects','⌘','对象与关系'],['evidence','▤','原件与断言'],['trace','⇄','批次与溯源'],['devices','◷','设备采集']];
function date(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime()) ? String(v) : d.toLocaleString('zh-CN',{hour12:false});}
function name(id){const e=list(state.data.entities).find(x=>x.entity_key===id)||list(state.data.lots).find(x=>x.lot_key===id);return e?e.name:String(id||'').slice(0,8);}
function tag(v){return '<span class="badge '+(['candidate','reported','forecast'].includes(v)?'amber':(['withdrawn','recalled','rejected'].includes(v)?'red':''))+'">'+esc(labels[v]||v||'未知')+'</span>';}
function btn(text, action, id='', extra=''){return '<button type="button" class="btn '+extra+'" data-action="'+action+'" data-id="'+esc(id)+'">'+esc(text)+'</button>';}
function empty(title='暂无记录',desc='登记并核验数据后，这里会展示相应信息。'){return '<div class="empty"><strong>'+esc(title)+'</strong>'+esc(desc)+'</div>';}
function table(headers,rows){return rows.length?'<div class="table-wrap"><table><thead><tr>'+headers.map(x=>'<th scope="col">'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':empty();}
function panel(title,body,action=''){return '<section class="panel"><div class="panel-head"><h2>'+esc(title)+'</h2>'+action+'</div>'+body+'</section>';}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4200);}
async function api(path,options={}){const headers={...(state.token?{Authorization:'Bearer '+state.token}:{}),...(options.headers||{})};if(options.body && !(options.body instanceof FormData))headers['Content-Type']='application/json';let r;try{r=await fetch('/api/v1'+path,{credentials:'same-origin',...options,headers});}catch(_){throw new Error('连接中断，或未收到服务回执。请保留原表单内容后重试；相同内容会复用请求标识，避免重复写入。');}let body;try{body=await r.json();}catch(_){throw new Error('服务未返回有效数据（'+r.status+'）');}if(!r.ok){const e=body.error||{};throw new Error((e.message||'请求失败')+(e.details?'\n'+JSON.stringify(e.details,null,2):'')+(e.request_id?'\n请求编号：'+e.request_id:''));}return Object.hasOwn(body,'data')?body.data:body;}
async function write(path,body,requestKey){const fingerprint=path+'|'+(body instanceof FormData?JSON.stringify(Array.from(body.entries()).map(([k,v])=>[k,v instanceof File?{name:v.name,size:v.size,lastModified:v.lastModified}:v])):JSON.stringify(body));const cache=state.pendingKeys;let key=requestKey||cache?.get(fingerprint);if(!key){key=crypto.randomUUID();cache?.set(fingerprint,key);}return api(path,{method:'POST',headers:{'Idempotency-Key':key},body:body instanceof FormData?body:JSON.stringify(body)});}
function download(value,label){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=label+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function showDialog(title,content){const d=$('#dialog');d.classList.remove('wide-dialog');d.innerHTML='<div class="dialog-head"><h2 id="dialog-title">'+esc(title)+'</h2><button class="close" aria-label="关闭对话框" data-action="close">×</button></div>'+content;if(!d.open)d.showModal();return d;}
function field(label,name,type='text',options='',hint=''){return '<label class="field '+(type==='textarea'||type==='multiple'?'full':'')+'"><span>'+esc(label)+'</span>'+(type==='textarea'?'<textarea name="'+name+'" rows="4">'+esc(options)+'</textarea>':type==='select'||type==='multiple'?'<select name="'+name+'" '+(type==='multiple'?'multiple':'')+'>'+options+'</select>':'<input class="input" name="'+name+'" type="'+type+'" '+(type==='file'?'':'value="'+esc(options)+'"')+'>')+(hint?'<small>'+esc(hint)+'</small>':'')+'</label>';}
function options(items,value,label){return items.map(x=>'<option value="'+esc(x[value])+'">'+esc(typeof label==='function'?label(x):x[label])+'</option>').join('');}
function form(title,fields,submit,callback,notice=''){state.pendingKeys=new Map();const d=showDialog(title,(notice?'<p class="hint">'+esc(notice)+'</p>':'')+'<form id="active-form"><div class="form-grid">'+fields+'</div><div class="form-error" role="alert"></div><div class="form-actions">'+btn('取消','close')+'<button class="btn primary" type="submit">'+esc(submit)+'</button></div></form>');$('#active-form',d).onsubmit=async event=>{event.preventDefault();const f=event.currentTarget;const b=$('button[type=submit]',f);b.disabled=true;$('.form-error',f).textContent='';try{const result=await callback(new FormData(f));await refresh();d.close();toast('已保存，并更新相关数据');if(result?.afterSave)await result.afterSave();}catch(e){$('.form-error',f).textContent=e.message;}finally{b.disabled=false;}};initPickers(d);return d;}
function details(title,value,extra=''){showDialog(title,extra+'<details><summary>查看完整授权数据</summary><pre class="code-panel">'+esc(JSON.stringify(value,null,2))+'</pre></details><div class="form-actions">'+btn('导出 JSON','download-detail')+btn('关闭','close')+'</div>');state.detail=value;}
function shell(){const title=navs.find(x=>x[0]===state.view)?.[2]||'数据总览';$('#app').innerHTML='<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">梁</div><div><strong>梁子湖</strong><small>AGRICULTURAL ONTOLOGY</small></div></div><nav class="nav" aria-label="主要导航">'+navs.filter(([id])=>!['trace','devices'].includes(id)).map(([id,icon,n])=>'<button class="'+(state.view===id?'active':'')+'" data-action="navigate" data-id="'+id+'" aria-current="'+(state.view===id?'page':'false')+'"><span class="symbol" aria-hidden="true">'+icon+'</span>'+n+'</button>').join('')+'<details class="nav-extensions" '+(['trace','devices'].includes(state.view)?'open':'')+'><summary>兼容扩展</summary>'+navs.filter(([id])=>['trace','devices'].includes(id)).map(([id,icon,n])=>'<button class="'+(state.view===id?'active':'')+'" data-action="navigate" data-id="'+id+'"><span class="symbol">'+icon+'</span>'+n+'</button>').join('')+'</details></nav><div class="sidebar-foot"><b>结构清楚，记录可追溯</b>概念 · 关系 · 事件 · 证据<br>本地工程环境 / 合成演示</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">农业数据空间 <span aria-hidden="true"> / </span> '+esc(title)+'</div><div class="account"><span class="badge gray">合成演示环境</span><span class="user-dot" aria-hidden="true">◉</span><span>'+esc(state.actor?(state.actor.roles||[]).map(x=>({admin:'管理员',operator:'录入员',reviewer:'审核员',viewer:'查看者'}[x]||x)).join(' / '):'尚未连接')+'</span>'+btn(state.actor?'切换身份':'连接','login')+'</div></header><main id="main" tabindex="-1"></main></div></div>';render();requestAnimationFrame(()=>{const nav=$('nav .active');if(nav&&window.innerWidth<=720)nav.scrollIntoView({block:'nearest',inline:'nearest'});});}
function heading(title,subtitle,actions=''){return '<div class="view-heading"><div><p class="eyebrow">LIANGZIHU · ONTOLOGY DATABASE</p><h1>'+title+'</h1><p class="subtext">'+subtitle+'</p></div><div class="actions">'+actions+'</div></div>';}
function render(){const main=$('#main');if(!main)return;if(!state.actor){main.innerHTML=heading('连接农业数据空间','登录后查看本体关系、生产记录和产品来源。')+'<div class="hero"><div><h2>一份可查来源的数据底座</h2><p>当前为本地合成演示环境。支持通过演示身份体验，也可使用管理员配置的访问令牌连接。</p></div>'+btn('连接工作台','login','','primary')+'</div>';return;}const views={overview:overview,objects:objects,trace:trace,evidence:evidenceView,domains:domains,intake:intake,devices:deviceIntake};main.innerHTML=loadNotice()+views[state.view]();if(state.view==='objects'&&state.graph)drawGraph(state.graph);}
const listSources={
 stats:{path:'/stats',label:'统计总数'},
 entities:{path:'/ontology/entities',label:'对象目录',limit:200},
 lots:{path:'/trace/lots',label:'物料批次',limit:200},
 events:{path:'/trace/events',label:'业务事件',limit:100},
 evidence:{path:'/evidence',label:'原始证据',limit:200},
 assertions:{path:'/assertions',label:'断言审核',limit:200},
 publications:{path:'/trace/publications',label:'公开版本',limit:100},
 packages:{path:'/ontology/packages',label:'领域包',limit:100},
 sets:{path:'/ontology/object-sets',label:'对象集',limit:100},
 devices:{path:'/devices',label:'设备',limit:100},
 policies:{path:'/device-policies',label:'采集计划',limit:100},
 deviceRecords:{path:'/device-records',label:'设备记录',limit:100},
 mappings:{path:'/ingestion/mappings',label:'来源映射',limit:100},
 receipts:{path:'/ingestion/receipts',label:'接入回执',limit:100}
};
function loadNotice(){
 const errors=state.refreshErrors||[];
 const limited=Object.entries(listSources).filter(([key,s])=>s.limit&&(state.data[key]?.has_more||state.data[key]?.truncated));
 const memberLimited=list(state.data.sets).filter(s=>s.truncated);
 const warning=limited.length||memberLimited.length;
 return '<aside class="load-status '+(errors.length?'error':warning?'warning':'')+'" aria-label="数据载入范围"><div class="load-status-title"><strong>'+(state.busy?'正在更新数据':errors.length?'数据未完整更新':warning?'当前展示部分数据':'当前工作台为单页数据视图')+'</strong>'+btn(state.busy?'更新中…':'刷新数据','refresh','','text')+'</div>'+
 (errors.length?'<p role="alert">本次刷新失败：'+errors.map(e=>esc(e.label)).join('、')+'。对应列表或统计已清空，不能据此认定没有业务记录。其他已成功返回的数据仍可查看。</p>':'')+
 (limited.length?'<p>以下列表仅载入接口顺序中的前 N 条：'+limited.map(([key,s])=>esc(s.label)+' '+list(state.data[key]).length+' 条（上限 '+s.limit+' 条）').join('；')+'。完整数据须通过对应 API 使用 limit / offset 分页获取。</p>':'')+
 (memberLimited.length?'<p>部分动态对象集成员也已截断：'+memberLimited.map(s=>esc(s.name||s.id)).join('、')+'。成员数量仅代表当前返回结果。</p>':'')+
 '<details><summary>数据范围与分页说明</summary><p class="load-status-hint">'+(state.busy?'当前列表可能仍为上次载入结果，待本次请求完成后更新。':'')+'页面列表与事件摘要仅涵盖当前载入数据；登记表单中的对象选择支持全库搜索与翻页；接口顺序不等于最近发生顺序。统计总数与列表条数分别展示。</p>'+
 '<details><summary>查看列表上限'+(errors.length?'与失败详情':'')+'</summary><p>'+Object.values(listSources).filter(s=>s.limit).map(s=>esc(s.label)+'最多 '+s.limit+' 条').join('；')+'。工作台不会自动拉取全库；超出范围请通过 API 分页查询。</p>'+
 (errors.length?'<ul>'+errors.map(e=>'<li>'+esc(e.label)+'：'+esc(e.message)+'</li>').join('')+'</ul>':'')+'</details></details></aside>';
}
async function refresh(){
 if(!state.actor||state.busy)return;
 const epoch=++state.refreshEpoch;state.busy=true;state.graph=null;state.graphKey='';state.objectSearchPage=null;state.objectOffset=0;state.search='';render();
 const entries=Object.entries(listSources);
 const values=await Promise.allSettled(entries.map(([key,s])=>api(s.path+(s.limit?'?limit='+s.limit+'&offset=0':''))));
 if(epoch!==state.refreshEpoch)return;
 const errors=[];
 values.forEach((v,index)=>{const [key,source]=entries[index];if(v.status==='fulfilled')state.data[key]=v.value;else{delete state.data[key];errors.push({key,label:source.label,message:v.reason?.message||'请求失败'});}});
 state.refreshErrors=errors;state.receiptPage=null;state.receiptStatus='';state.receiptOffset=0;state.busy=false;render();
 if(errors.length)toast('数据未完整更新，请查看页面中的载入提示。');
}
function overview(){const c=state.data.stats?.counts||{},metrics=[['本体对象',c.entities,'稳定身份与语义分类'],['本体版本',c.ontology_packages,'类、属性和关系定义'],['原始证据',c.evidence,'来源、原文与完整性'],['观测记录',c.observations,'按属性与单位校验']];return heading('数据库总览','农业知识底座：接收、映射、校验、关联与追溯。',btn('登记对象','new-entity')+btn('进入数据接入','navigate','intake','primary'))+'<div class="hero"><div><h2>让每条记录找到对应的结构与来源</h2><p>维护本体定义，明确来源字段含义，保留原始证据与处理版本，再向外部系统提供可查询的数据。</p><p class="hint">当前为本地合成演示。图像识别、业务判断、设备控制与农业决策由外部服务承担。</p></div></div><div class="metric-grid">'+metrics.map(([t,v,s])=>'<div class="metric"><div class="metric-label">'+t+'</div><strong>'+esc(v??'—')+'</strong><small>'+s+'</small></div>').join('')+'</div><div class="grid-two">'+panel('当前载入的接入回执',table(['来源','类型','状态'],list(state.data.receipts).slice(0,6).map(r=>[esc(r.source_id),esc(recordLabels[r.raw_envelope?.record_kind]||r.record_kind||r.raw_envelope?.record_kind),esc(intakeStates[r.status]||r.status)])),btn('进入接入队列','navigate','intake','text'))+panel('数据库工作流程','<div class="panel-body">'+[['1 · 定义本体','登记类、属性、关系及适用约束'],['2 · 对齐身份与来源','登记对象、对象分类与来源映射'],['3 · 校验并保留回执','不明确的信息进入待映射队列'],['4 · 查询与提供数据','通过对象关系、证据包和 API 输出']].map(([t,d])=>'<div class="mini-row"><div><strong>'+t+'</strong><small>'+d+'</small></div></div>').join('')+'</div>')+'</div>';}

function objects(){const page=state.objectSearchPage||{...state.data.entities,items:list(state.data.entities).slice(0,50),has_more:list(state.data.entities).length>50||state.data.entities?.has_more};const items=list(page);const graphPanel='<div class="toolbar"><label for="graph-root" class="hint">中心对象</label><select id="graph-root">'+options(list(state.data.entities),'entity_key','name')+'</select><label class="hint" for="graph-dimension">关系维度</label><select id="graph-dimension"><option value="">全部维度</option>'+['identity','space','production','material','event','evidence','observation','assertion','device'].map(x=>'<option value="'+x+'">'+labels[x]+'</option>').join('')+'</select>'+btn('展开关系','load-graph')+btn('搜索其他对象','graph-search')+btn('导出图数据','download-graph')+'</div><div id="network" class="graph-box">'+(state.graph?'':empty('以对象为中心，展开关系','选择对象后查看来自实际记录的多维连接。'))+'</div><div class="graph-legend"><span><i class="dot"></i>对象</span><span><i class="dot gold"></i>事件与物料</span><span><i class="dot blue"></i>观测与证据</span><span>箭头表示记录的关系方向，不自动代表因果。</span></div>';return heading('对象与关系','身份保持稳定，分类可以扩展；在多个维度中查找关联。',btn('登记对象','new-entity','','primary')+btn('赋予类型','assign-type')+btn('登记关系','new-relation'))+panel('多维关系网络','<div class="panel-body">'+graphPanel+'</div>')+panel('对象目录','<div class="panel-body toolbar"><input id="object-search" class="input" value="'+esc(state.search)+'" placeholder="搜索全库对象名称" aria-label="按名称筛选对象">'+btn('搜索','search')+'</div>'+table(['对象','身份类型','版本','操作'],items.map(e=>['<div class="table-main">'+esc(e.name)+'</div><div class="table-sub">'+esc(e.entity_key.slice(0,8))+'</div>',esc(types[e.entity_type]||e.entity_type),esc(e.revision),btn('查看','inspect',e.entity_key,'text')+btn('证据包','bundle',e.entity_key,'text')]))+'<div class="picker-pagination">'+btn('上一页','objects-prev')+'<span>当前第 '+((state.objectOffset||0)/50+1)+' 页'+(page?.has_more?' · 还有更多记录':'')+'</span>'+(page?.has_more?btn('下一页','objects-next'):'')+'</div>');}
function trace(){const lots=list(state.data.lots),pubs=list(state.data.publications);return heading('批次与溯源','生产批次与库存物料分开记录，追查每次投入、产出和流向。',btn('录入事件','new-event')+btn('登记物料批次','new-lot','','primary'))+panel('物料批次',table(['批次','可用量','已发货 / 已签收','操作'],lots.map(l=>['<div class="table-main">'+esc(l.name)+'</div><div class="table-sub">'+esc(l.product_type)+'</div>',esc(l.available_quantity)+' '+esc(l.unit),esc(l.shipped_quantity)+' / '+esc(l.received_quantity)+' '+esc(l.unit),btn('谱系','lineage',l.lot_key,'text')+btn('来源包','trace-bundle',l.lot_key,'text')+btn('发布','publish',l.lot_key,'text')+btn('召回','recall',l.lot_key,'text')])) )+panel('公开溯源版本',table(['产品批次','发布版本','发布时间','公开入口'],pubs.map(p=>[esc(name(p.lot_key)),'v'+esc(p.revision),esc(date(p.created_at)),'<a class="btn" href="/trace/'+encodeURIComponent(p.public_code)+'" target="_blank" rel="noopener">查看公众页 ↗</a> '+btn('二维码','qr',p.public_code,'text')])) )+panel('业务事件',table(['事件','发生时间','记录状态','详情'],list(state.data.events).slice().reverse().map(e=>[esc(labels[e.event_type]||e.event_type),esc(date(e.occurred_at)),tag(e.status),btn('参与对象与数量','event-detail',e.id,'text')])));}
function evidenceView(){const ev=list(state.data.evidence),as=list(state.data.assertions);return heading('证据与审核','保留原始材料，让观测、候选陈述与已采用事实各有位置。',btn('上传原始材料','upload','','primary'))+panel('原始证据',table(['材料','状态','校验摘要','操作'],ev.map(e=>['<div class="table-main">'+esc(e.public_summary||e.kind)+'</div><div class="table-sub">'+esc(labels[e.kind]||e.kind)+'</div>',tag(e.status),'<span class="table-sub">'+esc((e.content_hash||'').slice(0,16))+'…</span>',btn('查看','evidence-detail',e.id,'text')+(e.status==='active'?btn('撤回','withdraw',e.id,'text'):'')])) )+panel('断言审核',table(['陈述对象','内容','当前状态','操作'],as.map(a=>[esc(name(a.subject_key)),esc(a.value_json?.public_text||a.value_json?.text||JSON.stringify(a.value_json||{})),tag(a.status),btn('查看依据','assertion-detail',a.id,'text')+(a.status==='candidate'?btn('审核','review',a.id,'text'):'')])));}
function domains(){const packs=list(state.data.packages);return heading('本体管理','维护类、属性、关系和适用约束。显示名称可编辑，稳定标识保持引用一致。',btn('创建本体','new-package','','primary'))+'<div class="operation-guide">'+[['创建本体','定义领域内的类、属性与关系。','new-package'],['对象分类','将已有对象归入适用本体类。','assign-type'],['关联对象','连接对象并保留时间与依据。','new-relation'],['对象分组','动态筛选或保存固定成员。','new-set']].map(([t,h,a])=>'<div><strong>'+t+'</strong><p>'+h+'</p>'+btn('打开',a,'','text')+'</div>').join('')+'</div><div class="domain-grid">'+packs.map(p=>'<article class="domain-card"><span class="badge gray">v'+esc(p.version)+'</span><h3>'+esc(p.label||p.package_id)+'</h3><p>'+esc(p.description||'尚未填写本体说明')+'</p><p class="table-sub">'+esc(p.package_id)+'<br>'+esc(p.namespace)+'</p><p class="domain-counts">'+packageParts(p,'types').length+' 类 · '+packageParts(p,'properties').length+' 属性 · '+packageParts(p,'predicates').length+' 关系</p><div class="actions">'+btn('查看结构','package-detail',p.package_id+'@'+p.version,'text')+btn('编辑名称','package-labels',p.package_id+'@'+p.version,'text')+'</div></article>').join('')+'</div>'+panel('对象集',table(['名称','模式','成员','操作'],list(state.data.sets).map(s=>[esc(s.name),tag(s.mode),esc((s.current_members||s.members||[]).length)+(s.truncated?'（已截断）':''),btn('集合详情','set-detail',s.id,'text')])) )+'<details class="advanced-panel"><summary>高级导入与接口</summary><p class="hint">语义结构通过新版本发布；修改显示名称不会改变稳定标识。</p>'+btn('导入本体 JSON','advanced-package')+btn('查看接口定义','openapi')+'</details>';}
function packageParts(p,key){return p[key]||p.definition?.[key]||[];}
function packageById(id){const p=list(state.data.packages).find(x=>x.package_id+'@'+x.version===id);if(!p)throw Error('请刷新本体列表');return p;}
function valueTypeLabel(v){return {decimal:'十进制数值',integer:'整数',string:'文本',boolean:'布尔',enum:'枚举',datetime:'带时区时间'}[v]||v;}
function packageDetails(id){const p=packageById(id),ts=packageParts(p,'types'),ps=packageParts(p,'properties'),rs=packageParts(p,'predicates'),tn=v=>ts.find(t=>t.type_id===v)?.label||v;details(p.label||p.package_id,p,'<p class="subtext">'+esc(p.description||'尚未填写说明')+'</p><dl class="detail-grid"><dt>稳定标识 / 版本</dt><dd>'+esc(p.package_id)+' / '+esc(p.version)+'</dd><dt>命名空间</dt><dd>'+esc(p.namespace)+'</dd></dl>'+btn('编辑名称与说明','package-labels',id)+'<div class="ontology-structure">'+panel('类',table(['名称','稳定标识','身份类型','说明'],ts.map(t=>[esc(t.label),esc(t.type_id),esc(types[t.identity_type]||t.identity_type),esc(t.description||'—')])) )+panel('属性与适用约束',table(['名称 / 标识','适用类','类型 / 用途','单位与约束'],ps.map(v=>[esc(v.label)+'<div class="table-sub">'+esc(v.property_id)+'</div>',esc((v.applies_to||[]).map(tn).join('、')),esc(valueTypeLabel(v.value_type))+' / '+esc({attribute:'对象属性',observation:'观测',assertion:'断言'}[v.usage]||v.usage),esc(v.unit||'无单位')+' · '+(v.required?'必填':'可选')+' · '+(v.cardinality==='many'?'多值':'单值')+(v.enum_values?' · '+esc(v.enum_values.join(' / ')):'')+(v.minimum!==undefined?' · 最小 '+esc(v.minimum):'')+(v.maximum!==undefined?' · 最大 '+esc(v.maximum):'')])) )+panel('关系及端点约束',table(['名称 / 标识','起点 → 终点','维度'],rs.map(r=>[esc(r.label||relationName(r.predicate_id))+'<div class="table-sub">'+esc(r.predicate_id)+'</div>',esc((r.subject_semantic_types?.length?r.subject_semantic_types.map(tn):r.subject_types||[]).join('、'))+' → '+esc((r.object_semantic_types?.length?r.object_semantic_types.map(tn):r.object_types||[]).join('、')),esc(labels[r.dimension]||r.dimension)])) )+'</div>');$('#dialog').classList.add('wide-dialog');}
function packageLabels(id){const p=packageById(id),items=[['types','type_id','类名称'],['properties','property_id','属性名称'],['predicates','predicate_id','关系名称']];form('编辑本体名称与说明',field('本体显示名称','label','text',p.label||p.package_id)+field('本体说明','description','textarea',p.description||'')+items.map(([key,identity,title])=>'<section class="full form-section"><h3>'+title+'</h3>'+packageParts(p,key).map((x,i)=>field(x[identity],key+'_'+i,'text',x.label||relationName(x[identity]))).join('')+'</section>').join(''),'保存名称',f=>{const body={package_id:p.package_id,version:p.version,expected_revision:p.display_revision||1,label:need(f,'label','本体显示名称'),description:f.get('description').trim()};for(const [key,identity] of items)body[{types:'type_labels',properties:'property_labels',predicates:'predicate_labels'}[key]]=Object.fromEntries(packageParts(p,key).map((x,i)=>[x[identity],need(f,key+'_'+i,'显示名称')]));return write('/ontology/package-labels',body);},'只修改展示标签与说明，稳定标识保持不变。含义变化请发布新版本，系统检查显示版本以避免覆盖他人修改。');}

function relationName(value){const raw=String(value||'关系'),key=raw.split(/[\/#:]/).pop();return {locatedIn:'位于',participatesIn:'参与生产系统',monitors:'监测',partOf:'组成部分',source:'来源',target:'目标',subject:'描述对象',object:'关联对象',observes:'观测',hasEvidence:'引用证据',supportedBy:'证据支持',derivedFrom:'派生自',inputOf:'投入',outputOf:'产出',productionOrigin:'生产来源',dissolved_oxygen:'溶解氧',typeAssignment:'类型归属'}[key]||key;}
function nodeTitle(node){const kind=node.entity_type||node.type||'';return kind==='relation'?relationName(node.name||node.label):node.name||node.label||types[kind]||labels[kind]||kind||'记录';}
function drawGraph(graph){
 const target=$('#network');if(!target)return;
 const nodes=graph.nodes||[],edges=graph.edges||[];
 if(!nodes.length){target.innerHTML=empty('这个维度暂无关系','可以切换维度，或先登记有证据的限定关系。');return;}
 const groups=[[],[],[],[]],positions={},lookup={};
 nodes.forEach(n=>{const id=n.entity_key||n.id,kind=n.entity_type||n.type||'';lookup[id]=n;groups[id===state.graphKey?0:kind==='relation'?1:n.entity_key?2:3].push(n);});
 const height=Math.max(300,Math.max(...groups.map(g=>g.length))*86+110),width=900,xs=[112,335,558,781];
 groups.forEach((g,col)=>g.forEach((n,i)=>{positions[n.entity_key||n.id]=[xs[col],g.length===1?height/2:90+i*86];}));
 const headings=['中心对象','限定语义关系','相关对象','事件、观测与证据'].map((t,i)=>'<text x="'+xs[i]+'" y="30" text-anchor="middle" fill="#88967f" font-size="11">'+t+'</text>').join('');
 const lines=edges.map(e=>{const a=positions[e.subject_key||e.source],b=positions[e.object_key||e.target];if(!a||!b)return '';const going=b[0]>=a[0],sx=a[0]+(going?82:-82),ex=b[0]+(going?-84:84),bend=(sx+ex)/2;const d='M'+sx+' '+a[1]+' C'+bend+' '+a[1]+' '+bend+' '+b[1]+' '+ex+' '+b[1];return '<path d="'+d+'" fill="none" stroke="#c3d0b9" stroke-width="1.2" '+(e.status==='candidate'?'stroke-dasharray="5 4"':'')+' marker-end="url(#arrow)"><title>'+esc(relationName(e.predicate_id||e.predicate))+'</title></path>';}).join('');
 const cards=nodes.map(n=>{const id=n.entity_key||n.id,[x,y]=positions[id],kind=n.entity_type||n.type||'',center=id===state.graphKey,label=nodeTitle(n),category=types[kind]||{relation:'限定关系',event:'业务事件',evidence:'原始证据',observation:'观测记录',assertion:'断言',type:'概念分类'}[kind]||labels[kind]||'关联记录';const color=kind==='relation'?'#867744':/event|lot|package/.test(kind)?'#9b7c45':/evidence|observation|assertion/.test(kind)?'#588991':'#5c8554';return '<g tabindex="0" role="button" aria-label="查看 '+esc(label)+'" data-action="graph-node" data-id="'+esc(id)+'"><title>'+esc(label+' · '+category)+'</title><rect x="'+(x-82)+'" y="'+(y-26)+'" width="164" height="52" rx="8" fill="'+(center?'#e4edc9':'#fff')+'" stroke="'+color+'" stroke-width="'+(center?'1.8':'1')+'"/><circle cx="'+(x-65)+'" cy="'+(y-7)+'" r="3" fill="'+color+'"/><text x="'+(x-56)+'" y="'+(y-3)+'" fill="#345438" font-size="11">'+esc(label.length>12?label.slice(0,11)+'…':label)+'</text><text x="'+(x-56)+'" y="'+(y+14)+'" fill="#8a987f" font-size="10">'+esc(category)+'</text></g>';}).join('');
 const edgeRows=edges.map((e,i)=>[esc(nodeTitle(lookup[e.subject_key||e.source]||{name:e.subject_key||e.source})),esc(relationName(e.predicate_id||e.predicate)),esc(nodeTitle(lookup[e.object_key||e.target]||{name:e.object_key||e.target})),esc(graph.dimension_labels?.[e.dimension]||labels[e.dimension]||e.dimension),btn('依据与限定','graph-edge',String(i),'text')]);
 target.innerHTML='<div class="network-canvas"><svg class="network" style="height:'+height+'px" viewBox="0 0 '+width+' '+height+'" aria-label="当前对象的分层关系网络"><defs><marker id="arrow" markerWidth="8" markerHeight="6" refX="7" refY="3" orient="auto"><path d="M0 0L8 3L0 6" fill="#afc2a6"/></marker></defs>'+headings+lines+cards+'</svg></div><p class="graph-caption">'+nodes.length+' 个节点 · '+edges.length+' 条关系。点击对象可继续聚焦；关系明细保留方向、语义和来源依据。'+(graph.truncated?' 已达到查询预算，这是局部视图。':'')+'</p><details class="relation-details"><summary>展开关系明细（'+edges.length+' 条）</summary>'+table(['来源节点','关系语义','目标节点','维度','检查'],edgeRows)+'</details>';
 if($('#graph-root'))$('#graph-root').value=state.graphKey;if($('#graph-dimension'))$('#graph-dimension').value=state.dimension;
}
async function login(){const d=showDialog('连接本地数据空间','<p class="hint">演示身份仅适用于开启演示模式的本机服务，所有示例均为合成数据。</p><form id="login-form"><div class="form-grid">'+field('演示角色','role','select','<option value="admin">管理员 · 全部演示操作</option><option value="operator">录入员 · 登记数据</option><option value="reviewer">审核员 · 审核发布</option><option value="viewer">查看者 · 只读访问</option>')+field('或使用访问令牌','token','password','','令牌仅保留在当前页面内存，不写入浏览器存储。')+'</div><div class="form-error" role="alert"></div><div class="form-actions"><button type="submit" class="btn primary">连接工作台</button></div></form>');$('#login-form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),token=f.get('token').trim();try{state.token=token;if(token)state.actor=await api('/auth/me');else state.actor=await api('/auth/demo',{method:'POST',body:JSON.stringify({role:f.get('role')})});state.data={};state.graph=null;state.graphKey='';state.refreshErrors=[];state.busy=false;state.refreshEpoch++;d.close();shell();await refresh();}catch(err){state.token='';$('.form-error',d).textContent=err.message;}};}
function eventExample(kind){const ls=list(state.data.lots),ev=list(state.data.evidence).filter(e=>e.status==='active'),batch=list(state.data.entities).find(e=>e.entity_type==='production_batch');const f=i=>({lot_key:ls[i]?.lot_key||'请选择真实批次 UUID',quantity:'10',unit:ls[i]?.unit||'kg'});const p={event_type:kind,occurred_at:new Date().toISOString(),evidence_ids:ev[0]?[ev[0].id]:[]};if(kind==='harvest'){p.participants=[{entity_key:batch?.entity_key||'请选择生产批次 UUID',role:'production_origin'}];p.outputs=[f(0)];}else if(kind==='ship'){p.items=[f(0)];}else if(kind==='receive'){p.shipment_id=list(state.data.events).find(e=>e.event_type==='ship')?.id||'请选择发货事件 UUID';p.items=[f(0)];}else if(kind==='package'){p.participants=[{entity_key:list(state.data.entities).find(e=>e.entity_type==='package')?.entity_key||'请选择包装 UUID',role:'container'},{entity_key:ls[0]?.lot_key||'请选择物料 UUID',role:'contained_item'}];}else{p.inputs=[f(0)];p.outputs=[f(1)];if(kind==='split'){p.outputs[0].quantity='5';p.outputs.push({...f(2),quantity:'5'});}if(kind==='merge'){p.inputs.push(f(1));p.outputs=[{...f(2),quantity:'20'}];}if(kind==='transform')p.loss_quantity='0';}return p;}
async function action(which,id){if(await enhancedAction(which,id))return;if(which==='navigate'){state.view=id;shell();return;}if(which==='login')return login();if(which==='close')return $('#dialog').close();if(which==='refresh')return refresh();if(which==='download-detail')return download(state.detail,'授权数据');if(which==='download-graph'){if(state.graph)download(state.graph,'关系图数据');else toast('请先展开关系图');return;}if(which==='search'){state.search=$('#object-search').value;render();return;}if(which==='load-graph'){state.graphKey=$('#graph-root').value;state.dimension=$('#graph-dimension').value;state.graph=await api('/ontology/graph?entity_key='+encodeURIComponent(state.graphKey)+'&depth=2&limit=70&dimension='+encodeURIComponent(state.dimension||'all'));drawGraph(state.graph);return;}
if(which==='graph-edge'){const e=state.graph.edges[Number(id)];return details('关系语义与来源依据',e,'<p class="hint">关系：'+esc(relationName(e.predicate_id||e.predicate))+' · 维度：'+esc(state.graph.dimension_labels?.[e.dimension]||labels[e.dimension]||e.dimension)+'</p>');}
if(which==='focus-node'){state.graphKey=id;state.graph=await api('/ontology/graph?entity_key='+encodeURIComponent(id)+'&depth=2&limit=70&dimension='+encodeURIComponent(state.dimension||'all'));$('#dialog').close();state.view='objects';shell();return;}
if(which==='graph-node'){const n=state.graph.nodes.find(n=>(n.entity_key||n.id)===id);if(list(state.data.entities).some(e=>e.entity_key===id))return action('inspect',id);return details(n?.name||'关系节点',n);}
if(which==='inspect'){const e=await api('/ontology/entities/'+encodeURIComponent(id));return details(e.name,e,'<dl class="detail-grid"><dt>身份类型</dt><dd>'+esc(types[e.entity_type]||e.entity_type)+'</dd><dt>当前版本</dt><dd>'+esc(e.revision)+'</dd><dt>登记时间</dt><dd>'+esc(date(e.created_at))+'</dd><dt>身份标识</dt><dd>'+esc(e.entity_key)+'</dd></dl><div class="actions">'+btn('查看证据包','bundle',id)+btn('以此为中心','focus-node',id)+'</div>');}
if(which==='bundle'){const b=await api('/inference/bundles/'+encodeURIComponent(id));return details(name(id)+' · 证据包',b,'<div class="stat-split"><div class="metric"><div class="metric-label">观测记录</div><strong>'+b.observations.length+'</strong></div><div class="metric"><div class="metric-label">已采用 / 候选断言</div><strong>'+b.adopted_assertions.length+' / '+b.candidate_assertions.length+'</strong></div></div><p class="notice">检索到的材料不会自动成为推理前提。缺失项：'+esc((b.gaps||[]).map(g=>g.code).join('、')||'当前查询未报告缺口')+'</p>');}
if(which==='lineage'){const b=await api('/trace/lots/'+encodeURIComponent(id)+'/lineage?direction=upstream&depth=10');return details(name(id)+' · 上游物料谱系',b,'<p class="hint">仅依据投入产出关系追查，不把同处一地或共同运输视为物料来源。完整节点、事件及数量依据可展开或导出查看。</p><div class="actions">'+btn('查下游影响','downstream',id)+'</div>');}
if(which==='downstream')return details(name(id)+' · 下游谱系',await api('/trace/lots/'+encodeURIComponent(id)+'/lineage?direction=downstream&depth=10'));
if(which==='trace-bundle')return details(name(id)+' · 来源信息包',await api('/trace/lots/'+encodeURIComponent(id)+'/bundle'),'<p class="hint">包含批次来源、事件、证据和缺失项。这是经身份授权获取的内部信息包，不是公众页面。</p>');
if(which==='event-detail')return details('事件参与对象与数量',await api('/trace/events?event_id='+encodeURIComponent(id)));
if(which==='evidence-detail'){const e=list(state.data.evidence).find(e=>e.id===id);return details('证据详情',e,'<p class="hint">原始材料与公开摘要分开授权。校验哈希证明内容一致，不单独证明事实真实。</p>'+(e?.uri?.startsWith('asset://')?btn('下载原始材料','download-asset',id):''));}
if(which==='download-asset'){const r=await fetch('/api/v1/evidence/'+encodeURIComponent(id)+'/asset',{credentials:'same-origin',headers:state.token?{Authorization:'Bearer '+state.token}:{}});if(!r.ok)throw new Error('原始材料当前不可访问（'+r.status+'）');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=list(state.data.evidence).find(e=>e.id===id)?.metadata?.filename||'原始材料';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);return;}
if(which==='assertion-detail')return details('断言及来源依据',list(state.data.assertions).find(e=>e.id===id));
if(which==='package-detail')return details('领域包定义',list(state.data.packages).find(p=>p.package_id+'@'+p.version===id));
if(which==='set-detail')return details('对象集',list(state.data.sets).find(s=>s.id===id));
if(which==='openapi')return details('数据接口定义',await api('/openapi.json'));
if(which==='qr'){return showDialog('公开溯源二维码','<div class="public-qr"><img class="qr" src="/api/v1/public/trace/'+encodeURIComponent(id)+'/qr.svg" alt="公开溯源二维码"><div><p>公开码：'+esc(id)+'</p><a class="btn" href="/trace/'+encodeURIComponent(id)+'" target="_blank" rel="noopener">打开公众页</a><p class="hint">二维码使用当前服务地址。本机地址需替换为实际部署域名后，其他设备才能访问。</p></div></div>');}
if(which==='new-entity')return form('登记本体对象',field('对象名称','name')+field('身份类型','entity_type','select',Object.entries(types).filter(([k])=>k!=='material_lot').map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')),'登记对象',f=>write('/ontology/entities',{entity_type:f.get('entity_type'),name:f.get('name'),attrs:{synthetic:true}}),'名称相同不代表身份相同。物料批次请在“批次与溯源”中登记。');
if(which==='new-lot')return form('登记物料批次',field('批次名称','name')+field('产品概念或类型','product_type','text','https://example.org/product/rice')+field('计量单位','unit','select','<option value="kg">kg · 千克</option><option value="g">g · 克</option><option value="L">L · 升</option><option value="count">count · 件</option>')+field('关联生产批次（可选）','production_batch_key','select','<option value="">暂不关联</option>'+options(list(state.data.entities).filter(e=>e.entity_type==='production_batch'),'entity_key','name')),'登记批次',f=>{const p={name:f.get('name'),product_type:f.get('product_type'),unit:f.get('unit'),attrs:{synthetic:true}};if(f.get('production_batch_key'))p.production_batch_key=f.get('production_batch_key');return write('/trace/lots',p);},'新批次数量为零；实际产出通过带证据的采收或加工事件登记。');
if(which==='upload')return form('上传原始材料',field('材料文件','file','file')+field('信源类型','source_kind','select',Object.entries(labels).filter(([k])=>['document','image','video','sensor','weather','remote_sensing','manual','official_api'].includes(k)).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join(''))+field('公开摘要（可选）','public_summary','textarea','','仅填写允许公开的文字；原件不会因此自动公开。'),'保存材料',f=>write('/ingestion/assets',f),'上传材料将保存在本地私有资产目录，最大 2 MB。照片或视频上传不代表已经完成识别。');
if(which==='withdraw')return form('撤回证据',field('撤回原因','reason','textarea'),'确认撤回',f=>write('/evidence/withdrawals',{evidence_id:id,reason:f.get('reason')}),'这会保留历史记录，同时使依赖该证据的公开摘要停止正常展示。请确认影响后填写原因。');
if(which==='recall')return form('登记批次召回',field('召回原因','reason','textarea'),'确认登记召回',f=>write('/trace/recalls',{lot_key:id,reason:f.get('reason')}),'将追查该物料的下游批次，并更新相关公众页状态。当前操作仅作用于本地合成演示数据。');
if(which==='review')return form('审核候选断言',field('审核结论','status','select','<option value="accepted">采用该陈述</option><option value="rejected">不采用该陈述</option>')+field('审核依据与理由','rationale','textarea'),'提交审核',f=>write('/assertions/reviews',{assertion_id:id,status:f.get('status'),rationale:f.get('rationale')}),'采用陈述与质量放行分别管理；不能根据一条推测自动声明产品合格。');
if(which==='publish'){const ev=list(state.data.evidence).filter(e=>e.status==='active'),assertions=list(state.data.assertions).filter(a=>a.status==='accepted');return form('发布公开溯源摘要',field('产品名称','product_name','text',name(id))+field('公开产地名称','origin')+field('公开说明','description','textarea')+field('依赖证据','evidence_ids','multiple',options(ev,'id',e=>e.public_summary||e.kind),'选择该批次真实相关的证据，不能用无关材料补齐来源。')+field('公开陈述（可选）','assertion_ids','multiple',options(assertions,'id',a=>a.value_json?.public_text||a.predicate_id)),'审核并发布',f=>write('/trace/publications',{lot_key:id,summary:{product_name:f.get('product_name'),origin:f.get('origin'),description:f.get('description')},evidence_ids:f.getAll('evidence_ids'),assertion_ids:f.getAll('assertion_ids')}),'这里只发布审核后的摘要，原始报告、内部身份和人员信息不会自动公开。实际质量合格须有独立业务依据。');}
if(which==='new-set')return form('登记对象集',field('集合名称','name')+field('集合模式','mode','select','<option value="dynamic">动态集合 · 随查询更新</option><option value="snapshot">固定快照 · 固定当前成员</option>')+field('动态集合身份类型','entity_type','select',Object.entries(types).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join(''))+field('快照成员','member_keys','multiple',options(list(state.data.entities),'entity_key','name')),'保存集合',f=>write('/ontology/object-sets',f.get('mode')==='dynamic'?{name:f.get('name'),mode:'dynamic',filter:{entity_type:f.get('entity_type')}}:{name:f.get('name'),mode:'snapshot',member_keys:f.getAll('member_keys')}));
if(which==='advanced-event'){const d=form('高级事件录入',field('事件示例','example','select',['harvest','split','merge','transform','package','ship','receive'].map(x=>'<option value="'+x+'">'+labels[x]+'</option>').join(''))+field('结构化事件记录','json','textarea',JSON.stringify(eventExample('harvest'),null,2)),'校验并登记',f=>write('/trace/events',JSON.parse(f.get('json'))),'示例使用当前对象作为提示，提交前须逐项核对标识、数量、单位和凭证。拆批为一入多出，并批为多入一出；加工须显式记录损耗。');$('select[name=example]',d).onchange=e=>{$('textarea[name=json]',d).value=JSON.stringify(eventExample(e.target.value),null,2);};return;}
if(which==='advanced-package')return form('高级领域包注册',field('领域包 JSON','json','textarea',JSON.stringify({package_id:'example.new-domain',version:'1.0.0',namespace:'https://example.org/new-domain/',types:[{type_id:'https://example.org/new-domain/ProductionBatch',identity_type:'production_batch',label:'新品类生产批次'}],predicates:[],dependencies:[]},null,2)),'验证并注册',f=>write('/ontology/packages',JSON.parse(f.get('json'))),'领域包按命名空间与版本管理；同一版本定义不能被静默覆盖。');
if(which==='ingest'){const batchKey=crypto.randomUUID();return form('高级标准记录接入',field('接入信封 JSON','json','textarea',JSON.stringify({source_kind:'manual',synthetic:true,records:[{record_kind:'observation',payload:{subject_key:list(state.data.entities)[0]?.entity_key||'请选择对象UUID',property_id:'example.temperature',value:{value:'20.5',unit:'Cel'},observed_at:new Date().toISOString(),method:'synthetic_manual',evidence_ids:list(state.data.evidence).filter(e=>e.status==='active').slice(0,1).map(e=>e.id),origin:'reported'}}]},null,2)),'校验并接入',async f=>{const result=await write('/ingestion/records',JSON.parse(f.get('json')),batchKey);if(result.accepted_count!==result.receipts.length){await refresh();throw new Error('部分记录未接入；已成功条目会在重试时重放，避免重复写入。请仅修正失败条目，保留顺序与已成功条目的内容。\n'+JSON.stringify(result.receipts,null,2));}},'每条记录独立提交，本表单共用固定接入键。失败后仅修正失败条目，不要调整顺序、删除或修改已成功条目；新增业务请关闭后另开表单。模型候选、预报、观测和事件分别处理。');}
}

/* Structured workbench forms and bounded, server-paged resource selection. */
const pickerSources={entities:{path:'/ontology/entities',key:'entity_key',label:x=>x.name,search:true},lots:{path:'/trace/lots',key:'lot_key',label:x=>x.name+' · '+x.available_quantity+' '+x.unit},evidence:{path:'/evidence',key:'id',label:x=>x.public_summary||x.kind},packages:{path:'/ontology/packages',key:x=>x.package_id+'@'+x.version,label:x=>(x.label||x.package_id)+' · '+x.package_id+' · v'+x.version},events:{path:'/trace/events',key:'id',label:x=>(labels[x.event_type]||x.event_type)+' · '+date(x.occurred_at)},devices:{path:'/devices',key:'id',label:x=>x.name},policies:{path:'/device-policies',key:'id',label:x=>x.name}};
function picker(label,name,resource='entities',multi=false,filters={}){return '<div class="field full"><span>'+esc(label)+'</span><div class="resource-picker" data-picker="'+esc(resource)+'" data-name="'+esc(name)+'" data-multiple="'+multi+'" data-filters="'+esc(JSON.stringify(filters))+'"></div></div>';}
function recordKey(source,row){return typeof source.key==='function'?source.key(row):row[source.key];}
function picked(name,scope=$('#dialog')){return Array.from(scope.querySelector('.resource-picker[data-name="'+name+'"]')?._picker?.selected.values()||[]);}
function need(f,name,label){const value=String(f.get(name)||'').trim();if(!value)throw new Error('请填写或选择'+label);return value;}
function localNow(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function isoTime(value,label){if(!value||Number.isNaN(new Date(value).getTime()))throw new Error('请填写有效的'+label);return new Date(value).toISOString();}
function identityOptions(blank=false){const names=new Map(Object.entries(types).filter(([k])=>!['lot','material_lot'].includes(k)));for(const p of list(state.data.packages))for(const t of (p.definition?.types||[]))if(!names.has(t.identity_type))names.set(t.identity_type,t.identity_type);return (blank?'<option value="">不限身份类型</option>':'')+Array.from(names,([k,v])=>'<option value="'+esc(k)+'">'+esc(v)+' · '+esc(k)+'</option>').join('');}
function initPickers(scope=document){scope.querySelectorAll('[data-picker]').forEach(el=>{if(el._picker)return;const s=el._picker={source:pickerSources[el.dataset.picker],selected:new Map(),rows:[],offset:0,limit:12,q:'',draftQ:'',busy:false,epoch:0,filters:JSON.parse(el.dataset.filters||'{}')};el.addEventListener('click',async e=>{const b=e.target.closest('[data-pick]');if(!b)return;e.preventDefault();e.stopPropagation();const act=b.dataset.pick;if(act==='search'){s.q=$('[data-search]',el).value.trim();s.draftQ=s.q;s.offset=0;await loadPicker(el);}if(act==='prev'||act==='next'){s.offset=Math.max(0,s.offset+(act==='next'?s.limit:-s.limit));await loadPicker(el);}if(act==='remove'){s.selected.delete(b.dataset.key);renderPicker(el);el.dispatchEvent(new CustomEvent('pickerchange',{bubbles:true}));}});el.addEventListener('input',e=>{if(e.target.matches('[data-search]'))s.draftQ=e.target.value;});el.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-search]')){e.preventDefault();$('[data-pick=search]',el).click();}});el.addEventListener('change',e=>{if(!e.target.matches('[data-choice]'))return;const key=e.target.value;const row=s.rows.find(r=>String(recordKey(s.source,r))===key);if(e.target.checked){if(el.dataset.multiple!=='true')s.selected.clear();s.selected.set(key,row);}else s.selected.delete(key);renderPicker(el);el.dispatchEvent(new CustomEvent('pickerchange',{bubbles:true}));});loadPicker(el);});}
async function loadPicker(el){const s=el._picker,epoch=++s.epoch;s.busy=true;s.error='';renderPicker(el);const p=new URLSearchParams({...s.filters,limit:s.limit,offset:s.offset});if(s.source.search&&s.q)p.set('name_contains',s.q);try{const result=await api(s.source.path+'?'+p);if(epoch!==s.epoch)return;s.rows=list(result);s.hasMore=Boolean(result.has_more);s.error='';}catch(e){if(epoch!==s.epoch)return;s.rows=[];s.hasMore=false;s.error=e.message;}s.busy=false;renderPicker(el);}
function renderPicker(el){const s=el._picker,source=s.source;const rows=s.rows.filter(r=>!s.q||source.search||source.label(r).toLowerCase().includes(s.q.toLowerCase()));const chosen=Array.from(s.selected,([key,r])=>'<span class="selection-chip">'+esc(source.label(r))+'<input type="hidden" name="'+esc(el.dataset.name)+'" value="'+esc(key)+'"><button type="button" data-pick="remove" data-key="'+esc(key)+'" aria-label="移除 '+esc(source.label(r))+'">×</button></span>').join('');el.innerHTML='<div class="picker-search"><input class="input" data-search value="'+esc(s.draftQ??s.q)+'" aria-label="搜索'+esc(el.dataset.name)+'" placeholder="'+(source.search?'搜索全库对象名称':'筛选当前页；可继续翻页')+'"><button type="button" class="btn" data-pick="search">搜索</button></div><div class="picker-selected">'+(chosen||'<span class="hint">尚未选择</span>')+'</div><div class="picker-results" aria-busy="'+s.busy+'">'+(s.error?'<p class="form-error">'+esc(s.error)+'</p>':s.busy?'<p class="hint">正在查询…</p>':rows.length?rows.map(r=>{const key=String(recordKey(source,r));return '<label class="picker-choice"><input type="'+(el.dataset.multiple==='true'?'checkbox':'radio')+'" data-choice name="_picker_'+esc(el.dataset.name)+'" value="'+esc(key)+'" '+(s.selected.has(key)?'checked':'')+'><span>'+esc(source.label(r))+'<small>'+esc(r.entity_type?types[r.entity_type]||r.entity_type:r.status?labels[r.status]||r.status:key)+'</small></span></label>';}).join(''):'<p class="hint">这一页没有匹配记录。可更换条件或继续翻页。</p>')+'</div><div class="picker-pagination"><button type="button" class="btn text" data-pick="prev" '+(s.offset===0||s.busy?'disabled':'')+'>上一页</button><span>第 '+(Math.floor(s.offset/s.limit)+1)+' 页 · 每页 '+s.limit+' 条</span><button type="button" class="btn text" data-pick="next" '+(!s.hasMore||s.busy?'disabled':'')+'>下一页</button></div>';}
function manualEnvelope(kind,payload,f){return {record_kind:kind,payload,note:need(f,'note','填报说明'),source_id:'manual-form'};}
async function manualObservation(){let properties=[],request=0;const d=form('人工观测填报',picker('观测对象','subject_key')+field('已登记观测属性','property_id','select','<option value="">先选择观测对象</option>','仅显示该对象在观测时点适用的属性。')+field('属性值','value','text','','按来源原值填写；布尔值使用 true 或 false。')+field('单位','unit','select','<option value="">先选择属性</option>')+field('观测时间','observed_at','datetime-local',localNow())+field('观测方法','method','text','人工仪表读数')+field('填报说明','note','textarea')+picker('附加原始证据（可选）','evidence_ids','evidence',true)+'<p class="hint full" data-property-hint>没有可选属性时，请先完成对象分类与本体定义。</p>','保存人工观测',f=>{const p=properties.find(x=>x._choice===f.get('property_id'));if(!p)throw Error('请选择对象适用的已登记属性');const value=typedValue(p,need(f,'value','属性值'));return write('/ingestion/manual',manualEnvelope('observation',{subject_key:need(f,'subject_key','观测对象'),property_id:p.property_id,property_ref:{package_id:p.package_id,version:p.version,property_id:p.property_id},value:{value,...(p.unit?{unit:p.unit}:{})},observed_at:isoTime(f.get('observed_at'),'观测时间'),method:need(f,'method','观测方法'),evidence_ids:f.getAll('evidence_ids'),origin:'reported'},f));},'原始填报作为证据保存。后端统一校验对象类别、属性、单位和值类型，人工报告不会自动变为已证实结论。');const update=()=>{const p=properties.find(x=>x._choice===$('[name=property_id]',d).value);$('[name=unit]',d).innerHTML='<option value="'+esc(p?.unit||'')+'">'+esc(p?.unit||'无单位')+'</option>';$('[data-property-hint]',d).textContent=p?'值类型：'+valueTypeLabel(p.value_type)+'；本体：'+p.package_id+' v'+p.version+(p.cardinality==='many'?'；多值请填写 JSON 数组':'')+(p.minimum!==undefined?'；最小 '+p.minimum:'')+(p.maximum!==undefined?'；最大 '+p.maximum:'')+(p.enum_values?'；可选值：'+p.enum_values.join('、'):''):'此对象在观测时点没有已登记的适用属性，请先完成对象分类或本体定义。';};const load=async()=>{const n=++request,key=new FormData($('#active-form',d)).get('subject_key');properties=[];$('[name=property_id]',d).innerHTML='<option value="">正在查询适用属性…</option>';try{const result=key?await api('/ontology/properties?'+new URLSearchParams({entity_key:key,at:isoTime($('[name=observed_at]',d).value,'观测时间'),usage:'observation',limit:500,offset:0})):[];if(n!==request)return;properties=list(result).map((x,i)=>({...x,_choice:String(i)}));$('[name=property_id]',d).innerHTML='<option value="">请选择已登记属性</option>'+properties.map(x=>'<option value="'+x._choice+'">'+esc(x.label)+' · '+esc(x.package_id)+' v'+esc(x.version)+'</option>').join('');if(properties.length)$('[name=property_id]',d).value=properties[0]._choice;update();}catch(err){if(n===request){update();$('.form-error',d).textContent=err.message;}}};$('#active-form',d).addEventListener('pickerchange',e=>{if(e.target.dataset.name==='subject_key')load();});$('[name=observed_at]',d).onchange=load;$('[name=property_id]',d).onchange=update;}

async function manualAssertion(){let properties=[],epoch=0;const d=form('候选断言登记',picker('描述对象','subject_key')+field('已登记断言属性','predicate_id','select','<option value="">先选择对象</option>')+field('陈述内容或属性值','description','textarea','','按所选属性的值类型填写；这里只登记来源陈述，不判断真假。')+field('填报说明','note','textarea')+picker('附加原始证据（可选）','evidence_ids','evidence',true)+'<p class="hint full" data-assertion-hint>选择对象后查询它适用的断言属性。</p>','保存候选断言',f=>{const p=properties.find(x=>x._choice===f.get('predicate_id'));if(!p)throw Error('请选择对象适用的断言属性');return write('/ingestion/manual',manualEnvelope('assertion',{subject_key:need(f,'subject_key','描述对象'),predicate_id:p.property_id,property_ref:{package_id:p.package_id,version:p.version,property_id:p.property_id},value:{value:typedValue(p,need(f,'description','陈述内容')),...(p.unit?{unit:p.unit}:{})},evidence_ids:f.getAll('evidence_ids'),origin:'manual'},f));},'类型与单位校验只验证记录格式。候选、已采纳等业务状态与入库校验状态分别保存。');const describe=()=>{const p=properties.find(x=>x._choice===$('[name=predicate_id]',d).value);$('[data-assertion-hint]',d).textContent=p?'类型：'+valueTypeLabel(p.value_type)+(p.unit?'；单位：'+p.unit:'')+(p.enum_values?'；可选值：'+p.enum_values.join('、'):''):'此对象尚无适用断言属性，请先完善本体定义和对象分类。';};$('#active-form',d).addEventListener('pickerchange',async e=>{if(e.target.dataset.name!=='subject_key')return;const n=++epoch,key=new FormData($('#active-form',d)).get('subject_key');try{const r=key?await api('/ontology/properties?'+new URLSearchParams({entity_key:key,usage:'assertion',limit:500,offset:0})):[];if(n!==epoch)return;properties=list(r).map((x,i)=>({...x,_choice:String(i)}));$('[name=predicate_id]',d).innerHTML='<option value="">请选择已登记属性</option>'+properties.map(x=>'<option value="'+x._choice+'">'+esc(x.label)+' · '+esc(x.package_id)+'</option>').join('');if(properties.length)$('[name=predicate_id]',d).value='0';describe();}catch(err){$('.form-error',d).textContent=err.message;}});$('[name=predicate_id]',d).onchange=describe;}

function typeAssignment(){const d=form('赋予对象语义类型',picker('本体对象','entity_key')+picker('类型所属领域包','package_choice','packages')+field('语义类型','type_id','select','<option value="">先选择领域包</option>')+field('分类有效开始时间','valid_from','datetime-local',localNow(),'填写此分类在业务中开始生效的时间。此前观测不能使用此分类的属性。')+field('分类有效结束时间（可选）','valid_to','datetime-local'),'保存类型赋值',f=>{const p=picked('package_choice',d)[0];if(!p)throw Error('请选择领域包');return write('/ontology/type-assignments',{entity_key:need(f,'entity_key','本体对象'),package_id:p.package_id,version:p.version,type_id:need(f,'type_id','语义类型'),valid_from:isoTime(f.get('valid_from'),'分类有效开始时间'),...(f.get('valid_to')?{valid_to:isoTime(f.get('valid_to'),'分类有效结束时间')}:{})});},'对象身份保持稳定，语义类型表示它在某个领域版本中的分类。后端校验身份兼容性。');$('#active-form',d).addEventListener('pickerchange',event=>{if(!['package_choice','entity_key'].includes(event.target.dataset.name))return;const p=picked('package_choice',d)[0],e=picked('entity_key',d)[0];const ts=(p?.types||p?.definition?.types||[]).filter(t=>!e||t.identity_type==='*'||t.identity_type===e.entity_type);$('[name=type_id]',d).innerHTML='<option value="">选择兼容的语义类型</option>'+ts.map(t=>'<option value="'+esc(t.type_id)+'">'+esc(t.label)+' · '+esc(t.type_id)+'</option>').join('');});}
