function deviceIntake(){const devices=list(state.data.devices),policies=list(state.data.policies),records=list(state.data.deviceRecords);return heading('设备采集兼容扩展','已保留的网关与计划功能。设备运行由外部系统负责，数据库接收其原件和记录。',btn('刷新数据','refresh'))+'<div class="intake-grid">'+[['✎','人工填报','观测数值、现场巡检与业务事件。填报原文自动留存为证据。',btn('填写观测','manual-observation','','primary')+btn('记录事件','new-event')+btn('记录情况','manual-assertion')],['▧','原图与视频','保存原件，检查文件、图像质量与视频抽帧。处理结果与来源分别保留。',btn('上传原始材料','upload','','primary')],['⌁','摄像头与闸门','登记设备身份和绑定对象；边缘网关按已配置只读接口采集。',btn('登记设备','new-device','','primary')+btn('补录设备记录','device-record')],['◷','采集安排','设置常规间隔与重点时段，查看待采集记录。',btn('新增采集计划','new-policy','','primary')+btn('查看待采集','due-captures')]].map(([icon,title,text,actions])=>'<section class="intake-card"><span class="intake-icon">'+icon+'</span><h2>'+title+'</h2><p>'+text+'</p><div class="actions">'+actions+'</div></section>').join('')+'</div>'+panel('已登记设备',table(['设备','类别与接入标识','绑定对象','操作'],devices.map(x=>[esc(x.name),esc(x.device_kind==='camera'?'摄像头':'闸门')+'<div class="table-sub">'+esc(x.source_id)+' / '+esc(x.external_device_id)+'</div>',esc(name(x.bound_entity_key)),btn('接入信息','device-detail',x.id,'text')])) )+panel('采集计划',table(['计划','周期','状态','操作'],policies.map(x=>[esc(x.name),esc(x.interval_seconds)+' 秒<div class="table-sub">重点时段 '+esc((x.focus_windows||[]).length)+' 个</div>',tag(x.enabled?'active':'disabled'),btn(x.enabled?'停用':'启用','policy-toggle',x.id,'text')+btn('详情','policy-detail',x.id,'text')])) )+panel('设备记录',table(['类别','采集时间','重点程度','详情'],records.map(x=>[esc(labels[x.record_type]||x.record_type),esc(date(x.captured_at)),esc(x.priority==='focus'?'重点时段':'常规'),btn('查看','device-record-detail',x.id,'text')])) )+panel('接口与批量接入','<div class="panel-body"><p class="hint">设备登记与采集计划不会自行启动拉流或操作闸门。网关须由运维显式启动，URL 与访问令牌在网关环境中配置。本站只记录闸门状态。</p><div class="actions">'+btn('高级标准记录接入','ingest')+btn('查看接口定义','openapi')+'</div></div>');}
function deviceForm(){return form('登记现场设备',field('设备名称','name')+field('设备类别','device_kind','select','<option value="camera">摄像头</option><option value="gate">闸门状态接口</option>')+field('网关来源标识','source_id','text','edge-gateway-01','需与网关配置中的 source_id 一致。')+field('外部设备标识','external_device_id','text','','使用设备在源系统中的稳定编号。')+picker('绑定的田块、池塘或设施','bound_entity_key'),'登记设备',f=>write('/devices',{name:need(f,'name','设备名称'),device_kind:f.get('device_kind'),source_id:need(f,'source_id','网关来源标识'),external_device_id:need(f,'external_device_id','外部设备标识'),bound_entity_key:need(f,'bound_entity_key','绑定对象')}),'系统自动为设备建立本体身份。实际连接地址、接口令牌在边缘网关配置，登记后需要运维完成连接。');}
function policyForm(){const windowRow=()=>'<div class="editor-row focus-window">'+field('重点时段名称','focus_label','text','重点观察')+field('开始时间','focus_start','datetime-local',localNow())+field('结束时间','focus_end','datetime-local')+field('重点时段采集间隔（秒）','focus_interval','number','60')+'<button type="button" class="btn text" data-remove-window>移除此时段</button></div>';const d=form('安排设备采集',picker('设备','device_id','devices')+field('计划名称','name')+field('采集类型','record_type','select','<option value="camera_snapshot">摄像头快照</option><option value="camera_video">摄像头录像片段</option><option value="gate_status">闸门状态</option>')+field('开始时间','start_at','datetime-local',localNow())+field('结束时间（可选）','end_at','datetime-local')+field('常规采集间隔（秒）','interval_seconds','number','3600','60 秒至 7 天。重点时段可使用更短的间隔。')+'<section class="full form-section"><h3>重点观察时间</h3><div data-focus-windows></div><button type="button" class="btn" data-add-window>添加重点时段</button></section>','保存采集计划',f=>{const payload={device_id:need(f,'device_id','设备'),name:need(f,'name','计划名称'),record_type:f.get('record_type'),start_at:isoTime(f.get('start_at'),'开始时间'),interval_seconds:Number(need(f,'interval_seconds','采集间隔')),focus_windows:Array.from(d.querySelectorAll('.focus-window')).map(row=>{const get=n=>row.querySelector('[name='+n+']').value;return{label:get('focus_label').trim(),start_at:isoTime(get('focus_start'),'重点开始时间'),end_at:isoTime(get('focus_end'),'重点结束时间'),interval_seconds:Number(get('focus_interval'))};})};if(f.get('end_at'))payload.end_at=isoTime(f.get('end_at'),'结束时间');return write('/device-policies',payload);},'所有时间按本机时区填写并转换为带时区时间。待采集安排由网关执行，本页不会在后台自动启动采集。');$('#active-form',d).addEventListener('click',e=>{if(e.target.closest('[data-add-window]')){e.preventDefault();$('[data-focus-windows]',d).insertAdjacentHTML('beforeend',windowRow());}const remove=e.target.closest('[data-remove-window]');if(remove){e.preventDefault();remove.closest('.focus-window').remove();}});$('#active-form',d).addEventListener('pickerchange',event=>{if(event.target.dataset.name!=='device_id')return;const dev=picked('device_id',d)[0];if(dev)$('[name=record_type]',d).innerHTML=dev.device_kind==='gate'?'<option value="gate_status">闸门状态</option>':'<option value="camera_snapshot">摄像头快照</option><option value="camera_video">摄像头录像片段</option>';});}
async function deviceDetail(id){const item=list(await api('/devices?id='+encodeURIComponent(id)))[0];if(!item)throw Error('设备不存在或当前不可访问');const example={method:'POST',path:'/api/v1/device-records',headers:{Authorization:'Bearer <在网关环境中配置>', 'Idempotency-Key':'<稳定的采集请求标识>'},body:{device_id:item.id,source_record_id:'<源系统稳定记录编号>',record_type:item.device_kind==='gate'?'gate_status':'camera_snapshot',captured_at:'<带时区的实际采集时间>',evidence_ids:['<原件上传后返回的证据 UUID>'],priority:'routine',data:item.device_kind==='gate'?{state:'unknown'}:{},note:'<采集说明>'}};return details(item.name,item,'<dl class="detail-grid"><dt>设备 ID</dt><dd>'+esc(item.id)+' '+btn('复制设备 ID','copy-device-id',item.id,'text')+'</dd><dt>网关来源</dt><dd>'+esc(item.source_id)+'</dd><dt>外部设备</dt><dd>'+esc(item.external_device_id)+'</dd><dt>对接方式</dt><dd>网关配置映射只读摄像头或闸门接口。实际连接地址和访问令牌在网关环境中配置。</dd></dl><p class="hint">设备资料登记不代表已经连通。请通过设备记录核查实际采集结果。</p><details><summary>网关回传请求示例（供接口人员使用）</summary><p class="hint">先调用原件上传接口获得证据 UUID，再提交采集记录。计划内记录还需附带 policy_id 与 slot_at。</p><pre class="code-panel">'+esc(JSON.stringify(example,null,2))+'</pre></details>');}
function dueForm(){const d=showDialog('查看待采集安排','<p class="hint">一次查询最多覆盖 7 天。翻页保持相同时间范围，展示未完成的采集时点，不代表网关正在运行。</p><form id="due-form"><div class="form-grid">'+field('范围开始','since','datetime-local',new Date(Date.now()-86400000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16))+field('范围结束','as_of','datetime-local',localNow())+'</div><div class="form-actions"><button type="submit" class="btn primary">查询</button></div></form><div data-due-results></div>');let offset=0,query;const load=async()=>{const area=$('[data-due-results]',d);area.innerHTML='<p class="hint">正在查询…</p>';try{const result=await api('/device-captures/due?'+new URLSearchParams({...query,limit:25,offset}));area.innerHTML=table(['待采时间','设备','类型','重点'],list(result).map(x=>[esc(date(x.slot_at)),esc(list(state.data.devices).find(z=>z.id===x.device_id)?.name||x.device_id),esc(labels[x.record_type]||x.record_type),esc(x.priority==='focus'?(x.focus_labels||[]).join('、')||'重点':'常规')]))+'<div class="picker-pagination"><button type="button" class="btn" data-due-prev '+(!offset?'disabled':'')+'>上一页</button><span>第 '+(offset/25+1)+' 页</span><button type="button" class="btn" data-due-next '+(!result.has_more?'disabled':'')+'>下一页</button></div>';}catch(e){area.innerHTML='<p class="form-error">'+esc(e.message)+'</p>';}};$('#due-form',d).onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{query={since:isoTime(f.get('since'),'范围开始'),as_of:isoTime(f.get('as_of'),'范围结束')};offset=0;load();}catch(err){$('[data-due-results]',d).textContent=err.message;}};$('[data-due-results]',d).addEventListener('click',e=>{if(e.target.closest('[data-due-prev]')){offset=Math.max(0,offset-25);load();}if(e.target.closest('[data-due-next]')){offset+=25;load();}});}

async function contentKey(prefix,text){const bytes=typeof text==='string'?new TextEncoder().encode(text):text;return prefix+':'+Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');}
function mediaForm(){const d=form('上传原图、视频或材料',field('原始文件','file','file')+field('材料类型','source_kind','select','<option value="image">原始图像</option><option value="video">原始视频</option><option value="document">文本与报告</option><option value="remote_sensing">遥感原件</option><option value="manual">手工记录附件</option><option value="sensor">传感器原件</option><option value="weather">天气原件</option><option value="official_api">官方接口原件</option>')+field('来源标识','source_id','text','manual-upload')+field('材料摘要','public_summary','textarea','','只填写可公开的描述；原件仍受权限保护。'),'保存原件',async f=>{const file=f.get('file');if(!file||!file.size)throw Error('请选择非空原始文件');const evidence=await write('/ingestion/assets',f);return{afterSave:()=>mediaDetails(evidence)};},'默认单次请求上限 32 MiB，部署时可配置。原件保存后登记格式、大小与内容哈希。图像识别、视频抽帧和业务判断由外部服务完成。');$('[name=file]',d).accept='image/*,video/*,.pdf,.txt,.csv,.json,.xlsx,.docx';}
async function mediaDetails(value){const e=typeof value==='string'?await api('/evidence/'+encodeURIComponent(value)):value,m=e.metadata||{},p=m.processing||{};return details('原始材料与来源',e,'<div class="processing-summary"><strong>原件已登记</strong><dl class="detail-grid"><dt>文件名称</dt><dd>'+esc(m.filename||'未提供')+'</dd><dt>载体格式</dt><dd>'+esc(m.content_type||m.mime_type||e.kind)+'</dd><dt>文件大小</dt><dd>'+esc(m.size_bytes??m.size??'未提供')+' 字节</dd><dt>内容哈希</dt><dd>'+esc(e.content_hash||'未提供')+'</dd><dt>外部处理</dt><dd>'+esc(p.status==='not_requested'||!p.status?'尚未请求外部处理':'历史处理状态：'+p.status)+'</dd></dl><p class="hint">内容哈希用于核对原件完整性，不证明事实真实。原件可独立查询并交给外部服务处理；上传不会自动产生农业判断。</p></div>'+(e.uri?.startsWith('asset://')?btn('下载原始材料','download-asset',e.id):''));}

function deviceRecordForm(){const base=crypto.randomUUID();const d=form('补录设备采集记录',picker('设备','device_id','devices')+field('源记录编号','source_record_id','text','manual-'+crypto.randomUUID(),'同一采集记录使用稳定编号，重试不会重复登记。')+field('采集类型','record_type','select','<option value="camera_snapshot">摄像头快照</option><option value="camera_video">摄像头录像片段</option><option value="gate_status">闸门状态</option>')+field('采集时间','captured_at','datetime-local',localNow())+field('采集重要程度','priority','select','<option value="routine">常规采集</option><option value="focus">重点观察</option>')+'<div class="full" data-camera-fields>'+field('摄像头原图或视频','file','file')+field('视频时长（秒，可选）','duration_seconds','text')+'</div><div class="full" data-gate-fields hidden>'+field('闸门状态','gate_state','select','<option value="unknown">未知</option><option value="open">开启</option><option value="closed">关闭</option><option value="partial">部分开启</option>')+field('开度百分比（可选）','position_pct','text','','0 至 100，保留来源原始读数。')+'</div>'+field('记录说明','note','textarea')+picker('附加证据（可选）','evidence_ids','evidence',true),'保存设备记录',async f=>{const record_type=f.get('record_type'),device_id=need(f,'device_id','设备'),captured_at=isoTime(f.get('captured_at'),'采集时间');let data={},file;if(record_type==='gate_status'){data={state:f.get('gate_state'),...(f.get('position_pct').trim()?{position_pct:f.get('position_pct').trim()}:{})};file=new File([JSON.stringify({device_id,captured_at,data,note:f.get('note')})],'manual-gate-record.json',{type:'application/json',lastModified:0});}else{file=f.get('file');if(!file||!file.size)throw Error('请选择摄像头原图或视频');if(f.get('duration_seconds').trim())data.duration_seconds=f.get('duration_seconds').trim();}const body=new FormData();body.append('file',file);body.append('source_kind',record_type==='gate_status'?'manual':record_type==='camera_video'?'video':'image');body.append('source_id','manual-device-record');body.append('public_summary',f.get('note'));const fileHash=await contentKey('file',await file.arrayBuffer());const key=await contentKey(base,JSON.stringify({fileHash,kind:body.get('source_kind'),summary:body.get('public_summary')}));const evidence=await write('/ingestion/assets',body,key);return write('/device-records',{device_id,source_record_id:need(f,'source_record_id','源记录编号'),record_type,captured_at,priority:f.get('priority'),note:need(f,'note','记录说明'),data,evidence_ids:[evidence.id,...f.getAll('evidence_ids')]});},'用于人工补录真实采集结果。摄像头原件先保存；闸门读数原文也作为证据留存。此操作不会向设备发送控制指令。');const update=()=>{const type=$('[name=record_type]',d).value;$('[data-gate-fields]',d).hidden=type!=='gate_status';$('[data-camera-fields]',d).hidden=type==='gate_status';};$('[name=record_type]',d).onchange=update;$('#active-form',d).addEventListener('pickerchange',e=>{if(e.target.dataset.name!=='device_id')return;const dev=picked('device_id',d)[0];if(dev)$('[name=record_type]',d).innerHTML=dev.device_kind==='gate'?'<option value="gate_status">闸门状态</option>':'<option value="camera_snapshot">摄像头快照</option><option value="camera_video">摄像头录像片段</option>';update();});}
async function enhancedAction(which,id){
 if(await coreAction(which,id))return true;
 const actions={'manual-observation':manualObservation,'manual-assertion':manualAssertion,'new-event':eventForm,'new-package':packageForm,'assign-type':typeAssignment,'new-relation':relationForm,'new-set':objectSetForm,'new-device':deviceForm,'new-policy':policyForm,'due-captures':dueForm,'device-record':deviceRecordForm,'upload':mediaForm};
 if(actions[which]){await actions[which]();return true;}
 if(which==='device-detail'){await deviceDetail(id);return true;}
 if(which==='copy-device-id'){try{await navigator.clipboard.writeText(id);toast('设备 ID 已复制');}catch(_){toast('当前浏览器不允许自动复制，请选中设备 ID 手动复制。');}return true;}
 if(which==='policy-detail'){details('采集计划',list(await api('/device-policies?id='+encodeURIComponent(id)))[0]);return true;}
 if(which==='device-record-detail'){details('设备采集记录',list(await api('/device-records?id='+encodeURIComponent(id)))[0]);return true;}
 if(which==='policy-toggle'){const p=list(state.data.policies).find(x=>x.id===id);if(!p)throw Error('请刷新采集计划列表');form(p.enabled?'停用采集计划':'启用采集计划','<p class="hint full">'+esc(p.name)+'。'+(p.enabled?'停用后不再产生新的待采集时点；已登记数据保留。':'启用后网关可查询符合时间范围的采集时点。')+'</p>','确认'+(p.enabled?'停用':'启用'),()=>write('/device-policies/'+encodeURIComponent(id)+'/status',{enabled:!p.enabled}));return true;}
 if(which==='evidence-detail'){await mediaDetails(id);return true;}
 if(which==='new-entity'){form('登记本体对象',field('对象名称','name')+field('稳定身份类型','entity_type','select',identityOptions()),'登记对象',f=>write('/ontology/entities',{name:need(f,'name','对象名称'),entity_type:need(f,'entity_type','身份类型'),attrs:{synthetic:true}}),'名字相同不代表对象相同。新领域的身份类型须先注册领域包；对象建立后可再赋予语义类型。物料请使用批次登记。');return true;}
 if(which==='new-lot'){form('登记物料批次',field('批次名称','name')+field('产品概念或类型','product_type','text','https://example.org/product/rice')+field('计量单位','unit','select','<option value="kg">kg · 千克</option><option value="g">g · 克</option><option value="L">L · 升</option><option value="count">count · 件</option>')+picker('关联生产批次（可选）','production_batch_key','entities',false,{entity_type:'production_batch'}),'登记批次',f=>write('/trace/lots',{name:need(f,'name','批次名称'),product_type:need(f,'product_type','产品类型'),unit:f.get('unit'),attrs:{synthetic:true},...(f.get('production_batch_key')?{production_batch_key:f.get('production_batch_key')}:{})}),'新批次数量为零；采收或加工事件登记实际产出。');return true;}
 if(which==='search'||which==='objects-next'||which==='objects-prev'){if(which==='search'){state.search=$('#object-search').value.trim();state.objectOffset=0;}else state.objectOffset=Math.max(0,(state.objectOffset||0)+(which==='objects-next'?50:-50));state.objectSearchPage=await api('/ontology/entities?'+new URLSearchParams({name_contains:state.search,limit:50,offset:state.objectOffset||0}));render();return true;}
 if(which==='graph-search'){const d=form('选择图谱中心对象',picker('中心对象','entity_key'),'展开关系',async f=>{state.graphKey=need(f,'entity_key','中心对象');state.graph=await api('/ontology/graph?entity_key='+encodeURIComponent(state.graphKey)+'&depth=2&limit=70&dimension=all');const graph=state.graph,key=state.graphKey;return{afterSave:()=>{state.graph=graph;state.graphKey=key;state.dimension='';render();}};});return true;}
 return false;
}


const recordLabels={entity:'对象资料',observation:'观测',event:'事件',relationship:'对象关系',evidence:'原始证据',assertion:'外部断言'};
const intakeStates={needs_mapping:'待映射',validation_failed:'校验失败',stored:'已入库'};
const sourceCategories={device:'设备',manual:'人工填报',external_system:'外部系统',model:'外部模型'};
function intake(){const mappings=list(state.data.mappings),receipts=state.receiptPage?list(state.receiptPage):list(state.data.receipts).slice(0,50);return heading('数据接入','先确认来源、载体、记录类型与本体对应，再按规则校验入库。',btn('登记来源映射','new-mapping')+btn('接收结构化记录','new-receipt','','primary'))+'<div class="classification-strip">'+[['01 来源','哪个系统、设备或人员提供'],['02 载体','JSON、图片、视频或文档'],['03 记录类型','对象、观测、事件、关系或断言'],['04 本体对应','类、属性、对象身份及版本']].map(([a,b])=>'<div><strong>'+a+'</strong><span>'+b+'</span></div>').join('')+'</div><div class="intake-grid">'+[['人工填报','通过本体定义选择适用属性，填报原文自动成为来源证据。',btn('填写观测','manual-observation','','primary')+btn('记录事件','new-event')],['原始材料','保存原件、格式和哈希；外部处理结果通过独立接口回传。',btn('上传原件','upload','','primary')+btn('候选断言','manual-assertion')]].map(([t,h,a])=>'<section class="intake-card"><h2>'+t+'</h2><p>'+h+'</p><div class="actions">'+a+'</div></section>').join('')+'</div>'+panel('来源映射',table(['映射 / 版本','来源与结构版本','记录类型','操作'],mappings.map(m=>[esc(m.mapping_id)+' · v'+esc(m.version),esc(m.source_id)+'<div class="table-sub">'+esc(m.schema_version)+'</div>',esc(recordLabels[m.record_kind]||m.record_kind),btn('查看规则','mapping-detail',m.mapping_id+'@'+m.version,'text')+btn('用样本预览','mapping-preview',m.mapping_id+'@'+m.version,'text')])) )+panel('接入回执','<div class="panel-body toolbar"><label for="receipt-status">处理状态</label><select id="receipt-status"><option value="">全部</option>'+Object.entries(intakeStates).map(([k,v])=>'<option value="'+k+'" '+(state.receiptStatus===k?'selected':'')+'>'+v+'</option>').join('')+'</select>'+btn('查询回执','receipt-filter')+'</div>'+table(['来源记录','记录类型 / 载体','状态','操作'],receipts.map(r=>[esc(r.source_record_id||r.id)+'<div class="table-sub">'+esc(r.source_id)+'</div>',esc(recordLabels[r.record_kind||r.raw_envelope?.record_kind]||r.record_kind||r.raw_envelope?.record_kind)+'<div class="table-sub">'+esc(r.content_type||r.raw_envelope?.content_type||'application/json')+'</div>','<span class="badge '+(r.status==='validation_failed'?'red':r.status==='needs_mapping'?'amber':'')+'">'+esc(intakeStates[r.status]||r.status)+'</span>',btn('查看回执','receipt-detail',r.id||r.receipt_id,'text')+(r.status!=='stored'?btn('选择映射重试','receipt-retry',r.id||r.receipt_id,'text'):'' )]))+'<div class="picker-pagination">'+btn('上一页','receipt-prev')+'<span>第 '+((state.receiptOffset||0)/50+1)+' 页</span>'+((state.receiptPage?state.receiptPage.has_more:state.data.receipts?.has_more||list(state.data.receipts).length>50)?btn('下一页','receipt-next'):'')+'</div><div class="panel-body"><p class="hint">已入库仅表示通过规则校验，不表示内容已证实。待映射或校验失败的原文仍被保留；更换映射重试不会覆盖原文。</p></div>')+'<details class="advanced-panel"><summary>高级兼容接口</summary><div class="actions">'+btn('旧版批量接入','ingest')+btn('接口定义','openapi')+btn('设备采集扩展','navigate','devices')+'</div></details>';}
function mappingById(id){const m=list(state.data.mappings).find(x=>x.mapping_id+'@'+x.version===id);if(!m)throw Error('请刷新映射列表');return m;}
function mappingDetail(id){const item=mappingById(id),m={...item,...item.definition};details('来源映射 · '+m.mapping_id,m,'<dl class="detail-grid"><dt>来源 / 结构版本</dt><dd>'+esc(m.source_id)+' / '+esc(m.schema_version)+'</dd><dt>目标记录类型</dt><dd>'+esc(recordLabels[m.record_kind]||m.record_kind)+'</dd><dt>映射模式</dt><dd>'+esc(m.mode==='identity'?'标准结构直通':'字段映射')+'</dd></dl>'+table(['来源路径','目标路径','确定性转换'],(m.field_rules||m.definition?.field_rules||[]).map(r=>[esc(r.source_path),esc(r.target_path),esc('倍数 '+(r.scale??1)+'；偏移 '+(r.offset??0)+(r.unit?'；单位 '+r.unit:''))]))+'<p class="hint">来源路径与目标路径使用 JSON Pointer，例如 /temperature → /value/value。规则固定版本，修改需登记新版本。</p>'+btn('用样本预览','mapping-preview',id));}
async function mappingForm(){const props=list(await api('/ontology/properties?limit=500&offset=0'));const targetActions={observation:'create_observation',assertion:'create_assertion',entity:'create_entity',event:'create_event',relationship:'create_relation',evidence:'create_evidence'};const row=()=>'<div class="editor-row mapping-row">'+field('来源字段路径','source_path','text','','例如 /temperature')+field('目标字段路径','target_path','text','','例如 /value/value、/observed_at')+field('数值倍数（可选）','scale','text')+field('数值偏移（可选）','offset','text')+field('来源单位字段路径（可选）','source_unit_path','text','','例如 /unit；与预期来源单位一起填写。')+field('预期来源单位（可选）','source_unit','text','','例如 °C；来源不一致时报告校验错误。')+'<button type="button" class="btn text" data-remove-mapping>移除字段</button></div>';const d=form('登记来源映射',field('映射标识','mapping_id')+field('映射版本','version','text','1.0.0')+field('来源标识','source_id')+field('来源结构版本','schema_version','text','1')+field('来源类别','source_category','select',Object.entries(sourceCategories).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join(''))+field('载体格式','content_type','select','<option value="application/json">结构化 JSON</option>')+field('目标记录类型','record_kind','select',Object.entries(recordLabels).map(([k,v])=>'<option value="'+k+'" '+(k==='observation'?'selected':'')+'>'+v+'</option>').join(''))+field('映射模式','mode','select','<option value="fields">字段映射 · 从来源字段转换</option><option value="identity">标准结构直通 · 仍执行校验</option>')+picker('固定关联对象（可选）','subject_key')+'<div class="full form-section" data-mapping-observation>'+field('目标观测属性','property_choice','select','<option value="">请选择已登记属性</option>'+props.filter(p=>p.usage==='observation').map((p,i)=>'<option value="'+esc(p.package_id+'@'+p.version+'@'+p.property_id)+'">'+esc(p.label)+' · '+esc(p.package_id)+' v'+esc(p.version)+'</option>').join(''),'目标属性会固定本体版本与单位。对象的语义类仍由后端校验。')+field('观测方法','default_method','text','source_mapping')+'</div><section class="full form-section" data-field-rule-section><h3>来源字段 → 目标字段</h3><div data-mapping-rows>'+row()+'</div><button type="button" class="btn" data-add-mapping>添加字段映射</button></section><details class="full"><summary>其他固定字段（高级 JSON，可选）</summary>'+field('固定字段对象','defaults_json','textarea','{}','事件类型、证据引用等可在此配置。来源字段映射在其后执行。')+'</details>','保存映射',f=>{const kind=f.get('record_kind'),defaults=JSON.parse(f.get('defaults_json')||'{}');if(!defaults||Array.isArray(defaults)||typeof defaults!=='object')throw Error('固定字段必须是 JSON 对象');if(kind==='observation'){const p=props.find(p=>p.package_id+'@'+p.version+'@'+p.property_id===f.get('property_choice'));if(!p)throw Error('请选择已登记的目标观测属性');defaults.property_id=p.property_id;defaults.property_ref={package_id:p.package_id,version:p.version,property_id:p.property_id};defaults.value={...(defaults.value||{}),...(p.unit?{unit:p.unit}:{})};defaults.method=need(f,'default_method','观测方法');defaults.origin=defaults.origin||'reported';}const read=(r,n)=>r.querySelector('[name='+n+']').value.trim();const rules=f.get('mode')==='fields'?Array.from(d.querySelectorAll('.mapping-row')).map(r=>{const source_path=read(r,'source_path'),target_path=read(r,'target_path');if(!source_path||!target_path)throw Error('请填写来源和目标字段路径');return{source_path,target_path,...(read(r,'scale')?{scale:read(r,'scale')} :{}),...(read(r,'offset')?{offset:read(r,'offset')} :{}),...(read(r,'source_unit_path')||read(r,'source_unit')?{source_unit_path:read(r,'source_unit_path'),source_unit:read(r,'source_unit')}:{})};}):[];return write('/ingestion/mappings',{mapping_id:need(f,'mapping_id','映射标识'),version:need(f,'version','映射版本'),source_id:need(f,'source_id','来源标识'),schema_version:need(f,'schema_version','来源结构版本'),source_category:f.get('source_category'),content_type:'application/json',record_kind:kind,target_action:targetActions[kind],mode:f.get('mode'),...(f.get('subject_key')?{subject_key:f.get('subject_key')} :{}),field_rules:rules,defaults});},'映射定义解释字段含义，不自动猜测业务语义。保存后用来源样本预览，确认转换结果再入库。');$('#active-form',d).addEventListener('click',e=>{if(e.target.closest('[data-add-mapping]'))$('[data-mapping-rows]',d).insertAdjacentHTML('beforeend',row());if(e.target.closest('[data-remove-mapping]'))e.target.closest('.mapping-row').remove();});const sync=()=>{$('[data-mapping-observation]',d).hidden=$('[name=record_kind]',d).value!=='observation';$('[data-field-rule-section]',d).hidden=$('[name=mode]',d).value!=='fields';};$('[name=record_kind]',d).onchange=sync;$('[name=mode]',d).onchange=sync;sync();}
function receiptForm(mappingId){const selected=mappingId?mappingById(mappingId):null,ms=list(state.data.mappings);let lastPreview=null;const d=form(selected?'预览映射与接入样本':'接收结构化记录',field('来源标识','source_id','text',selected?.source_id||'')+field('来源记录编号','source_record_id','text','','来源系统中稳定且唯一的编号，用于重复提交检查。')+field('来源类别','source_category','select',Object.entries(sourceCategories).map(([k,v])=>'<option value="'+k+'" '+(k===(selected?.definition?.source_category||selected?.source_category||'device')?'selected':'')+'>'+v+'</option>').join(''))+'<div class="full form-section" data-model-producer hidden>'+field('模型名称','producer_name')+field('模型版本','producer_version')+'</div>'+field('载体格式','content_type','select','<option value="application/json">结构化 JSON</option>','图片、视频和报告请使用上传原件。')+field('来源结构版本','schema_version','text',selected?.schema_version||'1')+field('记录类型','record_kind','select',Object.entries(recordLabels).map(([k,v])=>'<option value="'+k+'" '+(k===(selected?.record_kind||'observation')?'selected':'')+'>'+v+'</option>').join(''))+field('使用映射','mapping_choice','select','<option value="">暂未对应 · 保存为待映射</option>'+ms.map(m=>'<option value="'+esc(m.mapping_id+'@'+m.version)+'" '+(selected===m?'selected':'')+'>'+esc(m.mapping_id)+' v'+esc(m.version)+' · '+esc(m.source_id)+'</option>').join(''))+field('来源原始内容','payload_json','textarea','{}','保留来源原值。JSON 解析成功不等于已通过本体校验。')+picker('已有原始证据（可选）','evidence_ids','evidence',true)+'<div class="full form-section"><div class="actions"><button type="button" class="btn" data-preview-receipt>预览转换与校验</button><span class="hint">预览不写入数据库。</span></div><div data-preview-result></div></div>','接收并保存回执',async f=>{const result=await write('/ingestion/receipts',body(f));return{afterSave:()=>receiptDetails(result)};},'系统依据来源契约、类型声明和格式校验分类。不明确的内容保留为待映射，不能仅凭字段名称猜测入库。');function body(f){const m=ms.find(m=>m.mapping_id+'@'+m.version===f.get('mapping_choice'));const payload=JSON.parse(f.get('payload_json'));if(!payload||Array.isArray(payload)||typeof payload!=='object')throw Error('来源内容必须是 JSON 对象');return{source_id:need(f,'source_id','来源标识'),source_record_id:need(f,'source_record_id','来源记录编号'),source_category:f.get('source_category'),content_type:'application/json',schema_version:need(f,'schema_version','来源结构版本'),record_kind:f.get('record_kind'),payload,evidence_ids:f.getAll('evidence_ids'),...(f.get('source_category')==='model'?{producer:{name:need(f,'producer_name','模型名称'),version:need(f,'producer_version','模型版本')}}:{}),...(m?{mapping_id:m.mapping_id,mapping_version:m.version}:{})};}$('[data-preview-receipt]',d).onclick=async()=>{const b=$('[data-preview-receipt]',d);b.disabled=true;try{lastPreview=await api('/ingestion/preview',{method:'POST',body:JSON.stringify(body(new FormData($('#active-form',d))))});$('[data-preview-result]',d).innerHTML=previewHTML(lastPreview);$('.form-error',d).textContent='';}catch(err){$('.form-error',d).textContent=err.message;}finally{b.disabled=false;}};}
function previewHTML(r){return '<strong>'+esc(intakeStates[r.status]||r.status||'预览结果')+'</strong><p class="hint">'+esc(r.status==='stored'?'样本满足本次校验；预览结果尚未保存。':'请检查映射或错误信息，再决定保存原始回执。')+'</p>'+(r.issues?.length?'<ul>'+r.issues.map(x=>'<li>'+esc(typeof x==='string'?x:x.message||JSON.stringify(x))+'</li>').join('')+'</ul>':'')+'<details open><summary>转换结果与校验详情</summary><pre class="code-panel">'+esc(JSON.stringify(r,null,2))+'</pre></details>';}
async function receiptDetails(value){const r=typeof value==='string'?await api('/ingestion/receipts/'+encodeURIComponent(value)):value;if(!r)throw Error('回执不存在或当前不可访问');details('接入回执 · '+(intakeStates[r.status]||r.status),r,'<dl class="detail-grid"><dt>来源记录</dt><dd>'+esc(r.source_id)+' / '+esc(r.source_record_id)+'</dd><dt>处理状态</dt><dd>'+esc(intakeStates[r.status]||r.status)+'</dd><dt>原文证据</dt><dd>'+esc(r.raw_evidence_id||'查看完整回执')+'</dd><dt>尝试次数</dt><dd>'+esc(Array.isArray(r.attempts)?r.attempts.length:r.attempts??r.attempt_count??'见详情')+'</dd></dl>'+(r.issues?.length?'<div class="notice error">'+r.issues.map(x=>esc(typeof x==='string'?x:x.message||JSON.stringify(x))).join('<br>')+'</div>':'')+(r.status!=='stored'?btn('选择映射重试','receipt-retry',r.id||r.receipt_id):'')+'<p class="hint">处理状态与事实真实性分开记录。重试复用原文与来源身份，保留每次映射和校验结果。</p>');}
function receiptRetry(id){const ms=list(state.data.mappings);form('选择映射并重试',field('使用映射版本','mapping_choice','select','<option value="">请选择已登记映射</option>'+ms.map(m=>'<option value="'+esc(m.mapping_id+'@'+m.version)+'">'+esc(m.mapping_id)+' v'+esc(m.version)+' · '+esc(m.source_id)+'</option>').join('')),'重试原始记录',async f=>{const m=ms.find(x=>x.mapping_id+'@'+x.version===f.get('mapping_choice'));if(!m)throw Error('请选择映射');const r=await write('/ingestion/receipts/'+encodeURIComponent(id)+'/retry',{mapping_id:m.mapping_id,mapping_version:m.version});return{afterSave:()=>receiptDetails(r)};},'重新处理已经保存的原始内容，不修改来源记录。来源与结构版本不匹配时会报告校验错误。');}
function typedValue(p,raw){if(p.cardinality==='many'){const values=JSON.parse(raw);if(!Array.isArray(values))throw Error('多值属性请填写 JSON 数组');return values;}if(p.value_type==='boolean'){if(!['true','false'].includes(raw))throw Error('布尔值请填写 true 或 false');return raw==='true';}if(p.value_type==='integer'){if(!/^-?\d+$/.test(raw))throw Error('请填写整数');return Number(raw);}return raw;}
function coreEntityForm(){let attributes=[];const d=form('登记本体对象',field('对象名称','name')+field('稳定身份类型','entity_type','select',identityOptions())+picker('所属本体（可选，可稍后分类）','entity_package','packages')+field('语义类','entity_class','select','<option value="">先选择本体</option>')+field('分类有效开始时间','entity_valid_from','datetime-local',localNow())+'<section class="full form-section"><h3>类中定义的对象属性</h3><div data-entity-attributes><p class="hint">选择语义类后显示适用属性。未分类对象可先登记稳定身份。</p></div></section>','登记对象',f=>{const p=picked('entity_package',d)[0],type_id=f.get('entity_class'),attrs={synthetic:true};for(const [i,a] of attributes.entries()){const raw=String(f.get('attribute_'+i)||'').trim();if(!raw){if(a.required)throw Error('请填写必填属性：'+a.label);continue;}attrs[a.property_id]={value:typedValue(a,raw),...(a.unit?{unit:a.unit}:{})};}if(p&&!type_id)throw Error('选择本体后请选择兼容的语义类');return write('/ontology/entities',{name:need(f,'name','对象名称'),entity_type:f.get('entity_type'),attrs,...(p&&type_id?{semantic_types:[{package_id:p.package_id,version:p.version,type_id,valid_from:isoTime(f.get('entity_valid_from'),'分类有效开始时间')}]}:{})});},'名称相同不代表身份相同。选择本体类后，只填写该类定义的属性；后端统一校验类型、单位和必填项。');const updateAttrs=()=>{const p=picked('entity_package',d)[0],t=$('[name=entity_class]',d).value;attributes=packageParts(p||{},'properties').filter(a=>a.usage==='attribute'&&(a.applies_to||[]).includes(t));$('[data-entity-attributes]',d).innerHTML=attributes.length?attributes.map((a,i)=>field(a.label+(a.required?' *':'')+(a.unit?'（'+a.unit+'）':''),'attribute_'+i,a.cardinality==='many'?'textarea':a.value_type==='enum'||a.value_type==='boolean'?'select':'text',a.cardinality==='many'?'':a.value_type==='enum'?'<option value="">请选择</option>'+a.enum_values.map(v=>'<option>'+esc(v)+'</option>').join(''):a.value_type==='boolean'?'<option value="">请选择</option><option value="true">是 · true</option><option value="false">否 · false</option>':'',a.cardinality==='many'?'多值属性，请填写 JSON 数组。':valueTypeLabel(a.value_type)+(a.minimum!==undefined?'；最小 '+a.minimum:'')+(a.maximum!==undefined?'；最大 '+a.maximum:''))).join(''):'<p class="hint">此类没有已声明的对象属性。</p>';};const updateClass=()=>{const p=picked('entity_package',d)[0],identity=$('[name=entity_type]',d).value;$('[name=entity_class]',d).innerHTML='<option value="">请选择兼容语义类</option>'+packageParts(p||{},'types').filter(t=>t.identity_type==='*'||t.identity_type===identity).map(t=>'<option value="'+esc(t.type_id)+'">'+esc(t.label)+'</option>').join('');updateAttrs();};$('#active-form',d).addEventListener('pickerchange',e=>{if(e.target.dataset.name==='entity_package')updateClass();});$('[name=entity_type]',d).onchange=updateClass;$('[name=entity_class]',d).onchange=updateAttrs;}
async function coreAction(which,id){if(which==='new-entity'){coreEntityForm();return true;}if(which==='package-detail'){packageDetails(id);return true;}if(which==='package-labels'){packageLabels(id);return true;}if(which==='new-mapping'){await mappingForm();return true;}if(which==='mapping-detail'){mappingDetail(id);return true;}if(which==='mapping-preview'||which==='new-receipt'){receiptForm(which==='mapping-preview'?id:null);return true;}if(which==='receipt-detail'){await receiptDetails(id);return true;}if(which==='receipt-retry'){receiptRetry(id);return true;}if(['receipt-filter','receipt-next','receipt-prev'].includes(which)){if(which==='receipt-filter'){state.receiptStatus=$('#receipt-status').value;state.receiptOffset=0;}else state.receiptOffset=Math.max(0,(state.receiptOffset||0)+(which==='receipt-next'?50:-50));state.receiptPage=await api('/ingestion/receipts?'+new URLSearchParams({...(state.receiptStatus?{status:state.receiptStatus}:{}),limit:50,offset:state.receiptOffset||0}));render();return true;}return false;}

async function publicPage(code){$('#app').innerHTML='<main class="public-shell" id="main"><div class="public-brand"><strong>梁子湖</strong><span class="badge gray">合成演示 · 公开溯源</span></div><div id="public-content" class="loading">正在读取公开来源信息…</div></main>';try{const value=await api('/public/trace/'+encodeURIComponent(code)),data=value.data||{},p=data.product||{},warning=value.status!=='published';$('#public-content').className='';$('#public-content').innerHTML='<section class="public-hero"><p class="eyebrow">ORIGIN · PEOPLE · EVIDENCE</p><h1>'+esc(p.product_name||'产品来源信息')+'</h1><p>'+esc(p.origin||'产地信息尚未公开')+'</p>'+tag(value.status)+'<p class="public-id">公开码 '+esc(code)+' · 版本 '+esc(value.revision)+'</p></section>'+(warning?'<div class="notice error"><strong>'+esc(labels[value.status]||'当前信息需要关注')+'</strong><br>'+esc(value.status==='recalled'?'该批次及相关产品已进入召回处置。历史质量声明已停止展示，请联系提供方确认处置范围与后续安排。':value.status==='withdrawn'?'本次公开摘要已撤回，旧声明不再作为当前有效信息。请联系提供方获取复核结果。':'当前公开信息不可用。请联系提供方核实，不要将历史摘要作为当前有效结论。')+'</div>':'')+'<div class="notice">本页面展示合成演示记录，用于说明溯源流程，不作为真实产品质量、认证或合格证明。</div>'+(!warning&&p.description?panel('产品说明','<div class="panel-body"><p class="subtext">'+esc(p.description)+'</p></div>'):'')+panel('来源与流转记录',(data.timeline||[]).length?'<div class="panel-body timeline">'+data.timeline.map(e=>'<div class="timeline-item"><b>'+esc(labels[e.event_type]||e.event_type)+'</b><p>'+esc(date(e.occurred_at))+' · '+esc(labels[e.occurrence_status]||e.occurrence_status||'已记录')+'</p></div>').join('')+'</div>':empty('当前没有可公开的流程记录','未展示不代表该环节不存在。'))+panel('已审核公开陈述',(data.quality_statements||[]).length?'<div class="panel-body">'+data.quality_statements.map(q=>'<p class="subtext">'+esc(typeof q==='string'?q:q.public_text||q.text||q.statement||'已审核陈述')+'</p>').join('')+'</div>':empty('暂无当前有效的公开质量陈述','来源记录与产品合格判定分别管理。'))+'<section class="panel"><div class="panel-body public-qr"><img class="qr" src="/api/v1/public/trace/'+encodeURIComponent(code)+'/qr.svg" alt="本产品公开来源二维码"><div><strong>分享这一份来源记录</strong><p class="hint">二维码指向当前服务地址。使用本机地址时，仅在本机可访问；部署后请使用正式域名。</p><p class="hint">查询时间 '+esc(date(new Date().toISOString()))+'</p></div></div></section><footer class="public-footer">梁子湖农业本体与产品溯源<br>本地工程演示 · 信息状态以当前查询结果为准</footer>';}catch(e){$('#public-content').className='';$('#public-content').innerHTML='<div class="notice error">'+esc(e.message)+'</div>'+empty('暂时无法显示公开信息','公开码可能尚未发布，或当前数据需要进一步核验。');}}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;try{await action(target.dataset.action,target.dataset.id);}catch(err){toast(err.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('g[role=button]'))e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));if(e.key==='Enter'&&e.target.id==='object-search'){e.preventDefault();action('search').catch(err=>toast(err.message));}});
(async()=>{const match=location.pathname.match(/^\/trace\/([^/]+)$/);if(match){await publicPage(decodeURIComponent(match[1]));return;}try{state.actor=await api('/auth/me');}catch(_){}shell();if(state.actor)await refresh();})();
